class FixedHeightToolBar final : public QToolBar {
public:
    FixedHeightToolBar(const QString &title, const int rowHeight, QWidget *parent)
        : QToolBar(title, parent), m_rowHeight(rowHeight)
    {
        setSizePolicy(QSizePolicy::Expanding, QSizePolicy::Fixed);
        setFixedHeight(m_rowHeight);
    }

    QSize sizeHint() const override
    {
        QSize hint = QToolBar::sizeHint();
        hint.setHeight(m_rowHeight);
        return hint;
    }

    QSize minimumSizeHint() const override
    {
        QSize hint = QToolBar::minimumSizeHint();
        hint.setHeight(m_rowHeight);
        return hint;
    }

private:
    int m_rowHeight = 44;
};

QString zoomPercentageText(const double zoom)
{
    const double percent = zoom * 100.0;
    const double rounded = std::round(percent);
    if (percent >= 25.0 || std::abs(percent - rounded) < 0.005) {
        return QStringLiteral("%1%").arg(qRound(percent));
    }

    QString value = QString::number(percent, 'f', 2);
    while (value.endsWith(QLatin1Char('0'))) value.chop(1);
    if (value.endsWith(QLatin1Char('.'))) value.chop(1);
    return value + QLatin1Char('%');
}

class HueRangePreview final : public QWidget {
public:
    explicit HueRangePreview(QWidget *parent = nullptr)
        : QWidget(parent)
    {
        setMinimumHeight(38);
        setSizePolicy(QSizePolicy::Expanding, QSizePolicy::Fixed);
        setToolTip(QObject::tr(
            "Bright colour shows the fully targeted hue core; the dimmed shoulders show feathering."));
    }

    void setRange(const HueSaturationRangeParameters &range)
    {
        m_range = range;
        m_range.normalise();
        update();
    }

protected:
    void paintEvent(QPaintEvent *) override
    {
        QPainter painter(this);
        const QRect area = rect().adjusted(1, 5, -1, -5);
        if (area.width() <= 1 || area.height() <= 1) return;

        const double inner = m_range.width * 0.5;
        for (int x = 0; x < area.width(); ++x) {
            const double hue = x * 360.0 / std::max(1, area.width() - 1);
            double distance = std::abs(hue - m_range.centre);
            distance = std::min(distance, 360.0 - distance);
            double weight = 0.0;
            if (distance <= inner) {
                weight = 1.0;
            } else if (m_range.feather > 1.0e-12
                       && distance < inner + m_range.feather) {
                const double t = (distance - inner) / m_range.feather;
                weight = t * t * (2.0 * t - 3.0) + 1.0;
            }
            QColor colour = QColor::fromHsvF(hue / 360.0, 1.0, 1.0);
            const QColor muted = palette().color(QPalette::Window);
            colour.setRedF(muted.redF() + (colour.redF() - muted.redF()) * weight);
            colour.setGreenF(muted.greenF() + (colour.greenF() - muted.greenF()) * weight);
            colour.setBlueF(muted.blueF() + (colour.blueF() - muted.blueF()) * weight);
            painter.setPen(colour);
            painter.drawLine(area.left() + x, area.top(), area.left() + x, area.bottom());
        }

        const auto xForHue = [&area](double hue) {
            hue = std::fmod(hue, 360.0);
            if (hue < 0.0) hue += 360.0;
            return area.left() + qRound(hue / 360.0 * std::max(1, area.width() - 1));
        };
        painter.setPen(QPen(palette().color(QPalette::Mid), 1.0));
        painter.drawRect(area.adjusted(0, 0, -1, -1));
        painter.setPen(QPen(palette().color(QPalette::Text), 1.0, Qt::DashLine));
        for (const double hue : {m_range.centre - inner - m_range.feather,
                                 m_range.centre + inner + m_range.feather}) {
            const int x = xForHue(hue);
            painter.drawLine(x, area.top(), x, area.bottom());
        }
        painter.setPen(QPen(palette().color(QPalette::Text), 1.0));
        for (const double hue : {m_range.centre - inner, m_range.centre + inner}) {
            const int x = xForHue(hue);
            painter.drawLine(x, area.top(), x, area.bottom());
        }
        painter.setPen(QPen(palette().color(QPalette::Highlight), 2.0));
        const int centreX = xForHue(m_range.centre);
        painter.drawLine(centreX, area.top() - 3, centreX, area.bottom() + 3);
    }

private:
    HueSaturationRangeParameters m_range;
};


bool layerTreeContainsCpuSpatialBlurSharpen(const QVector<LayerNode> &layers)
{
    QVector<const QVector<LayerNode> *> pending;
    pending.push_back(&layers);
    while (!pending.isEmpty()) {
        const QVector<LayerNode> *current = pending.takeLast();
        if (!current) continue;
        for (const LayerNode &layer : *current) {
            if (!layer.visible || layer.opacity <= 0.0) continue;
            for (const LayerEffect &effect : layer.layerEffects) {
                if (effect.enabled && layerEffectTypeHasRenderer(effect.type)) return true;
            }
            if (layer.type == LayerType::Smart) {
                for (const LiveFilter &filter : layer.liveFilters) {
                    if (!filter.enabled) continue;
                    switch (filter.adjustment.type) {
                    case AdjustmentType::GaussianBlur:
                    case AdjustmentType::BoxBlur:
                    case AdjustmentType::UnsharpMask:
                    case AdjustmentType::HighPass:
                    case AdjustmentType::SurfaceBlur:
                    case AdjustmentType::MotionBlur:
                    case AdjustmentType::RadialBlur:
                        return true;
                    default:
                        break;
                    }
                }
            }
            if (layer.type == LayerType::Adjustment) {
                switch (layer.adjustmentType) {
                case AdjustmentType::GaussianBlur:
                case AdjustmentType::BoxBlur:
                case AdjustmentType::UnsharpMask:
                case AdjustmentType::HighPass:
                case AdjustmentType::SurfaceBlur:
                case AdjustmentType::MotionBlur:
                case AdjustmentType::RadialBlur:
                    return true;
                default:
                    break;
                }
            } else if (layer.type == LayerType::Group && !layer.children.isEmpty()) {
                pending.push_back(&layer.children);
            }
        }
    }
    return false;
}

bool copyImagePatchExact(const QImage &sourcePatch,
                         QImage *destination,
                         const QPoint &destinationTopLeft)
{
    if (!destination || sourcePatch.isNull() || destination->isNull()
        || sourcePatch.format() != destination->format()
        || sourcePatch.depth() != destination->depth()
        || destinationTopLeft.x() < 0 || destinationTopLeft.y() < 0) {
        return false;
    }
    const QRect destinationRect(destinationTopLeft, sourcePatch.size());
    if (!destination->rect().contains(destinationRect)) {
        return false;
    }
    const qsizetype bytesPerPixel = sourcePatch.depth() / 8;
    const qsizetype rowBytes = static_cast<qsizetype>(sourcePatch.width())
        * bytesPerPixel;
    const qsizetype destinationOffset =
        static_cast<qsizetype>(destinationTopLeft.x()) * bytesPerPixel;
    if (bytesPerPixel <= 0 || rowBytes <= 0
        || rowBytes > sourcePatch.bytesPerLine()
        || destinationOffset < 0
        || destinationOffset + rowBytes > destination->bytesPerLine()) {
        return false;
    }

    destination->detach();
    for (int row = 0; row < sourcePatch.height(); ++row) {
        uchar *destinationLine = destination->scanLine(
            destinationTopLeft.y() + row);
        const uchar *sourceLine = sourcePatch.constScanLine(row);
        if (!destinationLine || !sourceLine) {
            return false;
        }
        std::memcpy(destinationLine + destinationOffset,
                    sourceLine,
                    static_cast<size_t>(rowBytes));
    }
    return true;
}
