    "colourManagement/showImportWarnings";

UntaggedImagePolicy storedUntaggedImagePolicy()
{
    const QString token = QSettings().value(
        QString::fromLatin1(UntaggedPolicySettingsKey),
        QStringLiteral("assume-srgb")).toString();
    return untaggedImagePolicyFromToken(token).value_or(
        UntaggedImagePolicy::AssumeSRgb);
}

void storeUntaggedImagePolicy(const UntaggedImagePolicy policy)
{
    QSettings().setValue(QString::fromLatin1(UntaggedPolicySettingsKey),
                         untaggedImagePolicyToken(policy));
}

QString shortenedFingerprint(const QByteArray &fingerprint)
{
    if (fingerprint.isEmpty()) return QObject::tr("Not available");
    const QString hex = QString::fromLatin1(fingerprint.toHex());
    return hex.size() > 24 ? hex.left(24) + QStringLiteral("…") : hex;
}

QString lutInspectorDomainSourceDisplayName(const LutDomainSource source)
{
    switch (source) {
    case LutDomainSource::DefaultRange:
        return QObject::tr("default [0, 1]");
    case LutDomainSource::DomainDirective:
        return QObject::tr("DOMAIN_MIN / DOMAIN_MAX");
    case LutDomainSource::InputRangeDirective:
        return QObject::tr("table-specific input range");
    case LutDomainSource::LegacyPersisted:
        return QObject::tr("migrated legacy range");
    }
    return QObject::tr("unknown range source");
}

QString lutDomainComponent(const double value)
{
    return QString::number(value, 'g', 9);
}

QString lutDomainDisplay(const std::array<double, 3> &minimum,
                         const std::array<double, 3> &maximum,
                         const LutDomainSource source)
{
    return QObject::tr("[%1, %2, %3] → [%4, %5, %6] · %7")
        .arg(lutDomainComponent(minimum[0]),
             lutDomainComponent(minimum[1]),
             lutDomainComponent(minimum[2]),
             lutDomainComponent(maximum[0]),
             lutDomainComponent(maximum[1]),
             lutDomainComponent(maximum[2]),
             lutInspectorDomainSourceDisplayName(source));
}

QString lutInterpolationDisplayName(const LutParameters &parameters)
{
    if (!parameters.hasCube()) return QObject::tr("Linear 1D");
    return parameters.interpolation == LutInterpolation::Tetrahedral
        ? QObject::tr("Tetrahedral") : QObject::tr("Trilinear");
}

QString lutProcessingDisplayName(const LutProcessingMode mode)
{
    switch (mode) {
    case LutProcessingMode::EncodedDocument:
        return QObject::tr("Encoded document values");
    case LutProcessingMode::LinearSrgb:
        return QObject::tr("Linear sRGB / Rec.709");
    case LutProcessingMode::RawComponents:
        return QObject::tr("Raw component values");
    }
    return QObject::tr("Unknown processing contract");
}

QString lutOperatorDisplayName(const LutOperatorProfile profile)
{
    switch (profile) {
    case LutOperatorProfile::Generic:
        return QObject::tr("Generic .cube");
    case LutOperatorProfile::TonyMcMapface:
        return QObject::tr("Tony McMapface");
    case LutOperatorProfile::AgXBaseSrgb:
        return QObject::tr("AgX Base sRGB");
    }
    return QObject::tr("Unknown operator profile");
}

struct LutEvaluationStatus {
    QString text;
    bool warning = false;
};

LutEvaluationStatus lutEvaluationStatus(const LutParameters &parameters,
                                        const QImage &documentImage)
{
    if (!parameters.hasData()) {
        return {QObject::tr("No LUT is loaded."), true};
    }
    if (documentImage.depth() > 32) {
        return {QObject::tr(
                    "Authoritative CPU · exact 16-bit document path. The native compositor remains 8-bit by design."),
                false};
    }
    const QString payloadFallback = CubeLut::gpuFallbackReason(parameters);
    if (!payloadFallback.isEmpty()) {
        return {payloadFallback, true};
    }

    const RenderBackend &backend = RenderBackend::instance();
    if (!backend.webGpuFoundationAvailable() || !backend.webGpuTileParityPassed()) {
        return {QObject::tr(
                    "Authoritative CPU · the native WebGPU foundation or base parity gate is unavailable."),
                true};
    }
    if (!backend.webGpuAdjustmentApproved(AdjustmentType::Lut)) {
        return {QObject::tr(
                    "Authoritative CPU · startup LUT conformance did not approve this adapter's WGSL path."),
                true};
    }
    return {QObject::tr(
                "Native WebGPU ready · RGBA16Float lookup with CPU-matched %1 evaluation. The complete layer hierarchy may still choose a local CPU fallback when another feature requires it.")
                .arg(lutInterpolationDisplayName(parameters)),
            false};
}

QString lutDiagnosticText(const LutParameters &parameters,
                          const QImage &documentImage)
{
    QStringList lines;
    const QString name = parameters.title.isEmpty()
        ? QFileInfo(parameters.sourceName).completeBaseName()
        : parameters.title;
    lines << QObject::tr("LUT: %1").arg(name.isEmpty()
                                            ? QObject::tr("Imported LUT")
                                            : name);
    lines << QObject::tr("Source label: %1").arg(parameters.sourceName.isEmpty()
                                                      ? QObject::tr("Not available")
                                                      : parameters.sourceName);
    QStringList tableParts;
    if (parameters.hasShaper()) {
        tableParts << QObject::tr("1D %1").arg(parameters.shaperSize);
    }
    if (parameters.hasCube()) {
        tableParts << QObject::tr("3D %1³").arg(parameters.cubeSize);
    }
    lines << QObject::tr("Tables: %1").arg(tableParts.join(QStringLiteral(" + ")));
    if (parameters.hasShaper()) {
        lines << QObject::tr("1D input domain: %1")
                     .arg(lutDomainDisplay(parameters.shaperDomainMin,
                                           parameters.shaperDomainMax,
                                           parameters.shaperDomainSource));
    }
    if (parameters.hasCube()) {
        lines << QObject::tr("3D input domain: %1")
                     .arg(lutDomainDisplay(parameters.cubeDomainMin,
                                           parameters.cubeDomainMax,
                                           parameters.cubeDomainSource));
    }
    lines << QObject::tr("Interpolation: %1")
                 .arg(lutInterpolationDisplayName(parameters));
    lines << QObject::tr("Operator profile: %1")
                 .arg(lutOperatorDisplayName(parameters.operatorProfile));
    lines << QObject::tr("Generic processing: %1")
                 .arg(lutProcessingDisplayName(parameters.processingMode));
    lines << QObject::tr("Strength: %1%").arg(parameters.strength, 0, 'f', 1);
    const QColorSpace colourSpace = documentImage.colorSpace();
    lines << QObject::tr("Document colour space: %1")
                 .arg(colourSpace.isValid() && !colourSpace.description().isEmpty()
                          ? colourSpace.description()
                          : QObject::tr("Untagged (compatibility sRGB treatment)"));
    lines << QObject::tr("Document precision: %1")
                 .arg(documentImage.depth() > 32
                          ? QObject::tr("16-bit integer")
                          : QObject::tr("8-bit integer"));
    lines << QObject::tr("Table fingerprint: %1")
                 .arg(QString::number(parameters.tableFingerprint, 16).rightJustified(16, QLatin1Char('0')));
    lines << QObject::tr("Evaluation: %1")
                 .arg(lutEvaluationStatus(parameters, documentImage).text);
    const QString warning = CubeLut::processingWarning(parameters, colourSpace);
    if (!warning.isEmpty()) lines << QObject::tr("Warning: %1").arg(warning);
    lines << QObject::tr("The LUT payload is embedded in the adjustment, project and user preset; the original .cube file is not required after saving.");
    return lines.join(QLatin1Char('\n'));
}

int vectorObjectIndexById(const LayerNode &layer, const QUuid &objectId)
{
    if (layer.type != LayerType::Vector || objectId.isNull()) return -1;
    for (int index = 0; index < layer.vectorData.objects.size(); ++index) {
        if (layer.vectorData.objects.at(index).id == objectId) return index;
    }
    return -1;
}

const VectorShape *vectorObjectById(const LayerNode &layer,
                                    const QUuid &objectId)
{
    const int index = vectorObjectIndexById(layer, objectId);
    return index >= 0 ? &layer.vectorData.objects.at(index) : nullptr;
}

VectorShape *vectorObjectById(LayerNode &layer, const QUuid &objectId)
{
    const int index = vectorObjectIndexById(layer, objectId);
    return index >= 0 ? &layer.vectorData.objects[index] : nullptr;
}

bool replaceVectorObjectById(LayerNode &layer, const VectorShape &shape)
{
    if (layer.type != LayerType::Vector || shape.id.isNull()) return false;
    VectorShape *target = vectorObjectById(layer, shape.id);
    if (!target) return false;
    *target = shape;
    layer.vectorData.normalise();
    return true;
}

bool svgSubtreeHasEditableContent(const LayerNode &layer)
{
    if (layer.type == LayerType::Vector || layer.type == LayerType::Text) return true;
    if (layer.type != LayerType::Group) return false;
    for (const LayerNode &child : layer.children) {
        if (svgSubtreeHasEditableContent(child)) return true;
    }
    return false;
}

bool svgTreeHasEditableContent(const QVector<LayerNode> &layers)
{
    for (const LayerNode &layer : layers) {
        if (svgSubtreeHasEditableContent(layer)) return true;
    }
    return false;
}

bool transformsNearlyEqual(const QTransform &left,
                           const QTransform &right,
                           const double epsilon = 1.0e-9)
{
    return std::abs(left.m11() - right.m11()) <= epsilon
        && std::abs(left.m12() - right.m12()) <= epsilon
        && std::abs(left.m13() - right.m13()) <= epsilon
        && std::abs(left.m21() - right.m21()) <= epsilon
        && std::abs(left.m22() - right.m22()) <= epsilon
        && std::abs(left.m23() - right.m23()) <= epsilon
        && std::abs(left.m31() - right.m31()) <= epsilon
        && std::abs(left.m32() - right.m32()) <= epsilon
        && std::abs(left.m33() - right.m33()) <= epsilon;
}

QString interpolationName(const TransformInterpolation interpolation)
{
    switch (interpolation) {
    case TransformInterpolation::NearestNeighbour: return QObject::tr("Nearest");
    case TransformInterpolation::Bilinear: return QObject::tr("Bilinear");
    case TransformInterpolation::Bicubic: return QObject::tr("Bicubic");
    case TransformInterpolation::Lanczos3: return QObject::tr("Lanczos 3");
    }
    return QObject::tr("Bilinear");
}

std::optional<OrthogonalDocumentTransform> orthogonalDocumentOperation(
    const TransformWorkflowState &workflow)
{
    if (!workflow.valid
        || workflow.kind != TransformWorkflowKind::OrthogonalDocument) {
        return std::nullopt;
    }
    switch (workflow.orthogonalDocumentOperation) {
    case static_cast<int>(OrthogonalDocumentTransform::FlipHorizontal):
        return OrthogonalDocumentTransform::FlipHorizontal;
    case static_cast<int>(OrthogonalDocumentTransform::FlipVertical):
        return OrthogonalDocumentTransform::FlipVertical;
    case static_cast<int>(OrthogonalDocumentTransform::Rotate90Clockwise):
        return OrthogonalDocumentTransform::Rotate90Clockwise;
    case static_cast<int>(OrthogonalDocumentTransform::Rotate90CounterClockwise):
        return OrthogonalDocumentTransform::Rotate90CounterClockwise;
    case static_cast<int>(OrthogonalDocumentTransform::Rotate180):
        return OrthogonalDocumentTransform::Rotate180;
    default:
        return std::nullopt;
    }
}

bool validTransformWorkflow(const TransformWorkflowState &workflow)
{
    const QTransform &matrix = workflow.documentTransform;
    const auto finiteAndBounded = [](const double value) {
        return std::isfinite(value) && std::abs(value) <= 1.0e9;
    };
    const bool finiteMatrix = transformMatrixIsFiniteAndBounded(matrix);
    if (!workflow.valid) {
        return false;
    }
    if (workflow.kind == TransformWorkflowKind::OrthogonalDocument) {
        return orthogonalDocumentOperation(workflow).has_value();
    }
    return workflow.kind == TransformWorkflowKind::LayerTransform && finiteMatrix
        && workflow.sourceBounds.isValid()
        && !workflow.sourceBounds.isEmpty()
        && finiteAndBounded(workflow.sourceBounds.x())
        && finiteAndBounded(workflow.sourceBounds.y())
        && finiteAndBounded(workflow.sourceBounds.width())
        && finiteAndBounded(workflow.sourceBounds.height())
        && finiteAndBounded(workflow.initialPivotDocument.x())
        && finiteAndBounded(workflow.initialPivotDocument.y())
        && finiteAndBounded(workflow.finalPivotDocument.x())
        && finiteAndBounded(workflow.finalPivotDocument.y())
        && workflow.mode >= static_cast<int>(TransformMode::FreeTransform)
        && workflow.mode <= static_cast<int>(TransformMode::Perspective)
        && workflow.interpolation >= static_cast<int>(TransformInterpolation::NearestNeighbour)
        && workflow.interpolation <= static_cast<int>(TransformInterpolation::Lanczos3)
        && transformHasSafeDomain(matrix, workflow.sourceBounds, 1.0e9);
}

QJsonObject pointToJson(const QPointF &point)
{
    return {{QStringLiteral("x"), point.x()},
            {QStringLiteral("y"), point.y()}};
}

QPointF pointFromJson(const QJsonObject &object, bool *ok)
{
    const QJsonValue xValue = object.value(QStringLiteral("x"));
    const QJsonValue yValue = object.value(QStringLiteral("y"));
    const bool valid = xValue.isDouble() && yValue.isDouble()
        && std::isfinite(xValue.toDouble()) && std::isfinite(yValue.toDouble());
    if (ok) {
        *ok = valid;
    }
    return valid ? QPointF(xValue.toDouble(), yValue.toDouble()) : QPointF();
}

QJsonObject transformWorkflowToJson(const TransformWorkflowState &workflow)
{
    QJsonObject object {
        {QStringLiteral("format"), QStringLiteral("VFXPhotoLabTransform")},
        {QStringLiteral("version"), 2},
        {QStringLiteral("kind"),
         workflow.kind == TransformWorkflowKind::OrthogonalDocument
             ? QStringLiteral("orthogonalDocument")
             : QStringLiteral("layerTransform")}
    };
    if (workflow.kind == TransformWorkflowKind::OrthogonalDocument) {
        object.insert(QStringLiteral("documentOperation"),
                      workflow.orthogonalDocumentOperation);
        return object;
    }

    const QTransform &t = workflow.documentTransform;
    QJsonObject matrix;
    matrix.insert(QStringLiteral("m11"), t.m11());
    matrix.insert(QStringLiteral("m12"), t.m12());
    matrix.insert(QStringLiteral("m13"), t.m13());
    matrix.insert(QStringLiteral("m21"), t.m21());
    matrix.insert(QStringLiteral("m22"), t.m22());
    matrix.insert(QStringLiteral("m23"), t.m23());
    matrix.insert(QStringLiteral("m31"), t.m31());
    matrix.insert(QStringLiteral("m32"), t.m32());
    matrix.insert(QStringLiteral("m33"), t.m33());
    object.insert(QStringLiteral("matrix"), matrix);
    object.insert(QStringLiteral("boundsX"), workflow.sourceBounds.x());
    object.insert(QStringLiteral("boundsY"), workflow.sourceBounds.y());
    object.insert(QStringLiteral("boundsWidth"), workflow.sourceBounds.width());
    object.insert(QStringLiteral("boundsHeight"), workflow.sourceBounds.height());
    object.insert(QStringLiteral("initialPivot"),
                  pointToJson(workflow.initialPivotDocument));
    object.insert(QStringLiteral("finalPivot"),
                  pointToJson(workflow.finalPivotDocument));
    object.insert(QStringLiteral("mode"), workflow.mode);
    object.insert(QStringLiteral("interpolation"), workflow.interpolation);
    object.insert(QStringLiteral("selectedPixels"), workflow.selectedPixels);
    return object;
}

std::optional<TransformWorkflowState> transformWorkflowFromJson(
    const QByteArray &bytes)
{
    QJsonParseError parseError;
    const QJsonDocument json = QJsonDocument::fromJson(bytes, &parseError);
    if (parseError.error != QJsonParseError::NoError || !json.isObject()) {
        return std::nullopt;
    }
    const QJsonObject object = json.object();
    const int version = object.value(QStringLiteral("version")).toInt();
    if (object.value(QStringLiteral("format")).toString()
            != QStringLiteral("VFXPhotoLabTransform")
        || (version != 1 && version != 2)) {
        return std::nullopt;
    }

    TransformWorkflowState workflow;
    workflow.valid = true;
    const QString kind = object.value(QStringLiteral("kind")).toString();
    if (version == 2 && kind != QStringLiteral("layerTransform")
        && kind != QStringLiteral("orthogonalDocument")) {
        return std::nullopt;
    }
    if (version == 2 && kind == QStringLiteral("orthogonalDocument")) {
        workflow.kind = TransformWorkflowKind::OrthogonalDocument;
        workflow.orthogonalDocumentOperation =
            object.value(QStringLiteral("documentOperation")).toInt(-1);
        return validTransformWorkflow(workflow)
            ? std::optional<TransformWorkflowState>(workflow) : std::nullopt;
    }

    workflow.kind = TransformWorkflowKind::LayerTransform;
    const QJsonObject matrix = object.value(QStringLiteral("matrix")).toObject();
    const QStringList matrixKeys = {
        QStringLiteral("m11"), QStringLiteral("m12"), QStringLiteral("m13"),
        QStringLiteral("m21"), QStringLiteral("m22"), QStringLiteral("m23"),
        QStringLiteral("m31"), QStringLiteral("m32"), QStringLiteral("m33")};
    for (const QString &key : matrixKeys) {
        if (!matrix.value(key).isDouble()
            || !std::isfinite(matrix.value(key).toDouble())) {
            return std::nullopt;
        }
    }
    const QStringList boundsKeys = {
        QStringLiteral("boundsX"), QStringLiteral("boundsY"),
        QStringLiteral("boundsWidth"), QStringLiteral("boundsHeight")};
    for (const QString &key : boundsKeys) {
        if (!object.value(key).isDouble()
            || !std::isfinite(object.value(key).toDouble())) {
            return std::nullopt;
        }
    }
    workflow.documentTransform = QTransform(
        matrix.value(QStringLiteral("m11")).toDouble(),
        matrix.value(QStringLiteral("m12")).toDouble(),
        matrix.value(QStringLiteral("m13")).toDouble(),
        matrix.value(QStringLiteral("m21")).toDouble(),
        matrix.value(QStringLiteral("m22")).toDouble(),
        matrix.value(QStringLiteral("m23")).toDouble(),
        matrix.value(QStringLiteral("m31")).toDouble(),
        matrix.value(QStringLiteral("m32")).toDouble(),
        matrix.value(QStringLiteral("m33")).toDouble());
    workflow.sourceBounds = QRectF(
        object.value(QStringLiteral("boundsX")).toDouble(),
        object.value(QStringLiteral("boundsY")).toDouble(),
        object.value(QStringLiteral("boundsWidth")).toDouble(),
        object.value(QStringLiteral("boundsHeight")).toDouble());
    bool initialOk = false;
    bool finalOk = false;
    workflow.initialPivotDocument = pointFromJson(
        object.value(QStringLiteral("initialPivot")).toObject(), &initialOk);
    workflow.finalPivotDocument = pointFromJson(
        object.value(QStringLiteral("finalPivot")).toObject(), &finalOk);
    workflow.mode = object.value(QStringLiteral("mode")).toInt(-1);
    workflow.interpolation = object.value(QStringLiteral("interpolation")).toInt(-1);
    workflow.selectedPixels = object.value(QStringLiteral("selectedPixels")).toBool(false);
    return initialOk && finalOk && validTransformWorkflow(workflow)
        ? std::optional<TransformWorkflowState>(workflow) : std::nullopt;
}


bool isUsableTransformQuad(const QPolygonF &quad)
{
    if (quad.size() != 4) {
        return false;
    }
    double orientation = 0.0;
    for (int index = 0; index < 4; ++index) {
        const QPointF point = quad.at(index);
        const QPointF next = quad.at((index + 1) % 4);
        const QPointF following = quad.at((index + 2) % 4);
        if (!std::isfinite(point.x()) || !std::isfinite(point.y())
            || QLineF(point, next).length() <= 1.0e-5) {
            return false;
        }
        const QPointF edgeA = next - point;
        const QPointF edgeB = following - next;
        const double cross = edgeA.x() * edgeB.y() - edgeA.y() * edgeB.x();
        if (!std::isfinite(cross) || std::abs(cross) <= 1.0e-7) {
            return false;
        }
        if (orientation == 0.0) {
            orientation = cross;
        } else if ((orientation > 0.0) != (cross > 0.0)) {
            return false;
        }
    }
    return true;
}

bool transformHasContinuousProjectiveDomain(const QTransform &transform,
                                            const QPolygonF &source)
{
    double sign = 0.0;
    for (const QPointF &point : source) {
        const double denominator = transform.m13() * point.x()
            + transform.m23() * point.y() + transform.m33();
        if (!std::isfinite(denominator) || std::abs(denominator) <= 1.0e-9) {
            return false;
        }
        if (sign == 0.0) {
            sign = denominator;
        } else if ((sign > 0.0) != (denominator > 0.0)) {
            return false;
        }
    }
    return true;
}

