class DeferredVfxClipboardMimeData final : public QMimeData {
public:
    DeferredVfxClipboardMimeData(ClipboardPayload payload,
                                 QByteArray cacheToken,
                                 const QImage &interoperabilityImage)
        : m_payload(std::move(payload))
    {
        setData(QString::fromLatin1(ClipboardCacheTokenMimeType),
                std::move(cacheToken));
        setImageData(interoperabilityImage);
    }

    QStringList formats() const override
    {
        QStringList result = QMimeData::formats();
        const QString privateType = QString::fromLatin1(ClipboardPayload::MimeType);
        if (!result.contains(privateType)) {
            result.prepend(privateType);
        }
        return result;
    }

    bool hasFormat(const QString &mimeType) const override
    {
        return mimeType == QString::fromLatin1(ClipboardPayload::MimeType)
            || QMimeData::hasFormat(mimeType);
    }

protected:
    QVariant retrieveData(const QString &mimeType,
                          QMetaType preferredType) const override
    {
        if (mimeType == QString::fromLatin1(ClipboardPayload::MimeType)) {
            if (!m_privatePayloadPrepared) {
                bool encoded = false;
                m_privatePayloadBytes = m_payload.toBytes(&encoded);
                if (!encoded) {
                    m_privatePayloadBytes.clear();
                }
                m_privatePayloadPrepared = true;
            }
            return m_privatePayloadBytes;
        }
        return QMimeData::retrieveData(mimeType, preferredType);
    }

private:
    ClipboardPayload m_payload;
    mutable bool m_privatePayloadPrepared = false;
    mutable QByteArray m_privatePayloadBytes;
};

