void MainWindow::closeEvent(QCloseEvent *event)
{
    if (documentMutationBusy()) {
        statusBar()->showMessage(
            m_exportInProgress
                ? tr("Please wait for the current export to finish or cancel it.")
                : tr("Please wait for the current edit to finish."),
            3000);
        event->ignore();
        return;
    }

    if (!m_exportQueueRecoveryPrepared
        && m_exportQueueController
        && m_exportQueueController->hasUnfinishedJobs()) {
        if (m_closeAfterExportQueueStops) {
            if (m_exportQueueDock) m_exportQueueDock->showAndRaise();
            statusBar()->showMessage(
                tr("The export queue is already preparing for close…"),
                3000);
            event->ignore();
            return;
        }
        QMessageBox prompt(this);
        prompt.setIcon(QMessageBox::Question);
        prompt.setWindowTitle(tr("Export Queue Is Still Active"));
        prompt.setText(tr("What should happen to the unfinished export jobs?"));
        prompt.setInformativeText(tr(
            "Preserved jobs are restored in a paused state on the next launch and must be reviewed before they can write files. Files already completed are kept."));
        QPushButton *preserveButton = prompt.addButton(
            tr("Preserve Jobs and Quit"), QMessageBox::AcceptRole);
        QPushButton *cancelJobsButton = prompt.addButton(
            tr("Cancel Jobs and Quit"), QMessageBox::DestructiveRole);
        QPushButton *keepOpenButton = prompt.addButton(
            tr("Keep Application Open"), QMessageBox::RejectRole);
        prompt.setDefaultButton(keepOpenButton);
        prompt.exec();
        if (prompt.clickedButton() == preserveButton) {
            m_closeAfterExportQueueStops = true;
            m_exportQueueRecoveryPrepared = true;
            m_exportQueueController->preserveForRestartAndWait();
            if (m_exportQueueDock) m_exportQueueDock->showAndRaise();
            statusBar()->showMessage(
                tr("Preserved unfinished export jobs for the next launch."));
        } else if (prompt.clickedButton() == cancelJobsButton) {
            m_closeAfterExportQueueStops = true;
            m_exportQueueController->cancelAll();
            if (m_exportQueueDock) m_exportQueueDock->showAndRaise();
            statusBar()->showMessage(
                tr("Cancelling the export queue before closing…"));
        }
        event->ignore();
        return;
    }

    const std::vector<DocumentSession *> openSessions = [&] {
        std::vector<DocumentSession *> result;
        result.reserve(m_sessions.size());
        for (const std::unique_ptr<DocumentSession> &candidate : m_sessions) {
            if (candidate && (candidate->document().hasImage()
                              || !candidate->summary().pixelSize.isEmpty())) {
                result.push_back(candidate.get());
            }
        }
        return result;
    }();

    DocumentSession *const activeBeforeClose = m_activeSession;
    for (DocumentSession *candidate : openSessions) {
        if (!maybeSaveChanges(candidate)) {
            // Saving an inactive untitled document temporarily activates it.
            // If the user cancels that save (or any later prompt), restore the
            // document they were actually working in before the quit attempt.
            if (activeBeforeClose && activeBeforeClose != m_activeSession
                && sessionById(activeBeforeClose->id())) {
                activateDocumentSession(activeBeforeClose);
            }
            if (m_exportQueueRecoveryPrepared && m_exportQueueController) {
                m_exportQueueController->resumeAfterAbortedShutdown();
                m_exportQueueRecoveryPrepared = false;
                statusBar()->showMessage(
                    tr("Quit was cancelled. Preserved export jobs remain available for review."),
                    5000);
            }
            event->ignore();
            return;
        }
    }

    resetPreviewControllerForSessionSwitch();
    saveWorkspaceLayout();
    event->accept();
}


void MainWindow::keyPressEvent(QKeyEvent *event)
{
    if (event && m_gradientGestureActive
        && event->key() == Qt::Key_Escape
        && event->modifiers() == Qt::NoModifier) {
        cancelGradientGesture();
        m_canvas->cancelPaintGesture();
        statusBar()->showMessage(tr("Gradient cancelled."), 2000);
        event->accept();
        return;
    }
    if (handleVectorNodeKeyPress(event)) return;

    if (event && m_activeTool == EditorTool::Pen
        && event->modifiers() == Qt::NoModifier) {
        if (event->key() == Qt::Key_Return || event->key() == Qt::Key_Enter) {
            finishPenPath();
            event->accept();
            return;
        }
        if (event->key() == Qt::Key_Escape) {
            if (!cancelCurrentPenSegment()) finishPenPath();
            event->accept();
            return;
        }
        if (event->key() == Qt::Key_Backspace) {
            QUuid id; LayerNode layer; VectorShape shape;
            if (m_penBuildingPath && selectedPathLayer(&id, &layer, &shape)
                && !shape.bezierPath.closed
                && !shape.bezierPath.nodes.isEmpty()) {
                m_selectedPathNodes = {penActiveEndpointIndex(shape)};
                deleteSelectedPathNodes();
                QUuid remainingId; LayerNode remainingLayer;
                VectorShape remainingShape;
                if (m_penBuildingPath
                    && selectedPathLayer(&remainingId, &remainingLayer,
                                         &remainingShape)
                    && !remainingShape.bezierPath.nodes.isEmpty()) {
                    m_selectedPathNodes = {
                        penActiveEndpointIndex(remainingShape)};
                    syncVectorPathOverlay();
                    rebuildToolOptionsBar();
                }
                event->accept();
                return;
            }
        }
    }
    if (event && m_transformActive && event->modifiers() == Qt::NoModifier) {
        if (event->key() == Qt::Key_Escape) {
            cancelTransformSession();
            event->accept();
            return;
        }
        if (event->key() == Qt::Key_Return || event->key() == Qt::Key_Enter) {
            applyTransformSession();
            event->accept();
            return;
        }
    }
    if (event && event->key() == Qt::Key_Delete
        && event->modifiers() == Qt::NoModifier) {
        QWidget *focus = QApplication::focusWidget();
        const bool layerTreeFocused = m_layerTree
            && (focus == m_layerTree || m_layerTree->isAncestorOf(focus));
        const bool canvasFocused = m_canvas
            && (focus == m_canvas || focus == m_canvas->viewport()
                || m_canvas->isAncestorOf(focus));
        if (layerTreeFocused || canvasFocused) {
            deleteOrClearFocusedTarget();
            event->accept();
            return;
        }
    }
    QMainWindow::keyPressEvent(event);
}

bool MainWindow::eventFilter(QObject *watched, QEvent *event)
{
    if (event && event->type() == QEvent::KeyPress
        && m_canvas
        && (watched == m_canvas || watched == m_canvas->viewport())) {
        auto *keyEvent = static_cast<QKeyEvent *>(event);
        if (m_gradientGestureActive
            && keyEvent->key() == Qt::Key_Escape
            && keyEvent->modifiers() == Qt::NoModifier) {
            cancelGradientGesture();
            m_canvas->cancelPaintGesture();
            statusBar()->showMessage(tr("Gradient cancelled."), 2000);
            return true;
        }
        if (handleVectorNodeKeyPress(keyEvent)) return true;
    }

    if (watched == m_canvasTextEditor && event) {
        if (event->type() == QEvent::KeyPress) {
            auto *keyEvent = static_cast<QKeyEvent *>(event);
            if (keyEvent->key() == Qt::Key_Escape) {
                cancelCanvasTextEditing();
                return true;
            }
            if ((keyEvent->key() == Qt::Key_Return
                 || keyEvent->key() == Qt::Key_Enter)
                && keyEvent->modifiers().testFlag(Qt::ControlModifier)) {
                commitCanvasTextEditing();
                return true;
            }
        } else if (event->type() == QEvent::FocusOut
                   && !m_canvasTextEditCommitting) {
            QTimer::singleShot(0, this, [this] {
                if (!m_canvasTextEditor || !m_canvasTextEditor->isVisible()
                    || m_canvasTextEditor->hasFocus()) {
                    return;
                }
                QWidget *focus = QApplication::focusWidget();
                const bool inspectorFocused = m_inspectorDock
                    && focus
                    && (focus == m_inspectorDock
                        || m_inspectorDock->isAncestorOf(focus));
                if (!inspectorFocused) {
                    commitCanvasTextEditing();
                }
            });
        }
    }
    return QMainWindow::eventFilter(watched, event);
}

