void MainWindow::buildMenusAndToolOptionsBar()
{
    QMenu *fileMenu = menuBar()->addMenu(tr("&File"));
    fileMenu->addAction(m_newAction);
    fileMenu->addAction(m_newFromClipboardAction);
    fileMenu->addSeparator();
    fileMenu->addAction(m_openImageAction);
    fileMenu->addAction(m_openProjectAction);
    QMenu *svgMenu = fileMenu->addMenu(tr("SVG"));
    svgMenu->addAction(m_openSvgAction);
    svgMenu->addAction(m_importSvgAction);
    svgMenu->addSeparator();
    svgMenu->addAction(m_exportSvgAction);
    svgMenu->addAction(m_exportSelectedSvgAction);
    fileMenu->addSeparator();
    fileMenu->addAction(m_saveAction);
    fileMenu->addAction(m_saveAsAction);
    fileMenu->addAction(m_exportAction);
    fileMenu->addAction(m_productionExportAction);
    fileMenu->addSeparator();
    fileMenu->addAction(m_closeAction);
    fileMenu->addAction(m_closeOthersAction);
    fileMenu->addAction(m_closeAllAction);
    fileMenu->addSeparator();
    fileMenu->addAction(tr("Quit"), QKeySequence::Quit, qApp, &QApplication::closeAllWindows);

    QMenu *editMenu = menuBar()->addMenu(tr("&Edit"));
    editMenu->addAction(m_undoAction);
    editMenu->addAction(m_redoAction);
    editMenu->addSeparator();
    editMenu->addAction(m_cutAction);
    editMenu->addAction(m_copyAction);
    editMenu->addAction(m_copyMergedAction);
    editMenu->addAction(m_pasteAction);
    editMenu->addSeparator();
    QMenu *vectorAppearanceEditMenu = editMenu->addMenu(tr("Vector Appearance"));
    vectorAppearanceEditMenu->addAction(m_swapVectorFillStrokeAction);
    vectorAppearanceEditMenu->addAction(m_resetVectorFillStrokeAction);
    vectorAppearanceEditMenu->addSeparator();
    vectorAppearanceEditMenu->addAction(m_copyVectorAppearanceAction);
    vectorAppearanceEditMenu->addAction(m_pasteVectorAppearanceAction);
    vectorAppearanceEditMenu->addSeparator();
    vectorAppearanceEditMenu->addAction(m_vectorAppearancePresetsAction);
    editMenu->addSeparator();
    QMenu *transformWorkflowMenu = editMenu->addMenu(tr("Transform"));
    transformWorkflowMenu->addAction(m_transformAgainAction);
    transformWorkflowMenu->addAction(m_repeatTransformAction);
    transformWorkflowMenu->addAction(m_transformAndDuplicateAction);
    transformWorkflowMenu->addSeparator();
    transformWorkflowMenu->addAction(m_copyTransformValuesAction);
    transformWorkflowMenu->addAction(m_pasteTransformValuesAction);
    editMenu->addSeparator();
    editMenu->addAction(m_clearContentsAction);
    editMenu->addSeparator();
    editMenu->addAction(m_colourManagementPreferencesAction);

    QMenu *imageMenu = menuBar()->addMenu(tr("&Image"));
    QMenu *colourManagementMenu = imageMenu->addMenu(tr("Colour Management"));
    colourManagementMenu->addAction(m_documentColourInfoAction);
    colourManagementMenu->addAction(m_displayColourManagementAction);
    colourManagementMenu->addAction(m_openColorIOAction);
    colourManagementMenu->addSeparator();
    colourManagementMenu->addAction(m_assignProfileAction);
    colourManagementMenu->addAction(m_convertProfileAction);
    imageMenu->addSeparator();
    QMenu *imageTransformMenu = imageMenu->addMenu(tr("Transform"));
    imageTransformMenu->addAction(m_flipImageHorizontalAction);
    imageTransformMenu->addAction(m_flipImageVerticalAction);
    imageTransformMenu->addSeparator();
    imageTransformMenu->addAction(m_rotateImageClockwiseAction);
    imageTransformMenu->addAction(m_rotateImageCounterClockwiseAction);
    imageTransformMenu->addAction(m_rotateImage180Action);
    imageMenu->addSeparator();
    imageMenu->addAction(m_imageSizeAction);
    imageMenu->addAction(m_canvasSizeAction);
    imageMenu->addSeparator();
    imageMenu->addAction(m_revealAllAction);
    imageMenu->addAction(m_fitCanvasToSelectionAction);
    imageMenu->addAction(m_fitCanvasToSelectedLayersAction);
    imageMenu->addSeparator();
    imageMenu->addAction(m_trimTransparentPixelsAction);
    imageMenu->addAction(m_trimCornerColourAction);

    QMenu *selectMenu = menuBar()->addMenu(tr("&Select"));
    selectMenu->addAction(m_selectAllAction);
    selectMenu->addAction(m_deselectAction);
    selectMenu->addAction(m_invertSelectionAction);
    selectMenu->addSeparator();

    auto addSelectionSourceModes = [this](QMenu *menu, const bool maskSource) {
        struct ModeEntry {
            const char *label;
            SelectionCombineMode mode;
        };
        const ModeEntry entries[] = {
            {QT_TR_NOOP("Replace Selection"), SelectionCombineMode::Replace},
            {QT_TR_NOOP("Add to Selection"), SelectionCombineMode::Add},
            {QT_TR_NOOP("Subtract from Selection"), SelectionCombineMode::Subtract},
            {QT_TR_NOOP("Intersect with Selection"), SelectionCombineMode::Intersect},
        };
        for (const ModeEntry &entry : entries) {
            QAction *action = menu->addAction(tr(entry.label));
            connect(action, &QAction::triggered, this, [this, maskSource, entry] {
                if (maskSource) {
                    loadLayerMaskSelection(entry.mode);
                } else {
                    loadLayerAlphaSelection(entry.mode);
                }
            });
        }
    };
    m_loadLayerAlphaSelectionMenu = selectMenu->addMenu(tr("Load Layer Alpha"));
    m_loadLayerAlphaSelectionMenu->setToolTip(
        tr("Use the current raster layer's stored pixel alpha in document space."));
    addSelectionSourceModes(m_loadLayerAlphaSelectionMenu, false);
    m_loadLayerMaskSelectionMenu = selectMenu->addMenu(tr("Load Layer Mask"));
    m_loadLayerMaskSelectionMenu->setToolTip(
        tr("Use the current layer's stored mask coverage, including inversion, even when the mask is disabled."));
    addSelectionSourceModes(m_loadLayerMaskSelectionMenu, true);

    selectMenu->addSeparator();
    selectMenu->addAction(m_featherSelectionAction);
    selectMenu->addAction(m_expandSelectionAction);
    selectMenu->addAction(m_contractSelectionAction);
    selectMenu->addAction(m_smoothSelectionAction);
    selectMenu->addAction(m_refineSelectionAction);
    selectMenu->addSeparator();
    selectMenu->addAction(m_showSelectionEdgesAction);

    QMenu *layerMenu = menuBar()->addMenu(tr("&Layer"));
    layerMenu->addAction(m_addRasterLayerAction);
    layerMenu->addAction(m_addGroupAction);
    QMenu *adjustmentMenu = layerMenu->addMenu(tr("New Adjustment Layer"));
    adjustmentMenu->addAction(tr("Exposure"), this, [this] {
        addAdjustment(AdjustmentType::Exposure);
    });
    adjustmentMenu->addAction(tr("Contrast"), this, [this] {
        addAdjustment(AdjustmentType::Contrast);
    });
    adjustmentMenu->addAction(tr("Saturation"), this, [this] {
        addAdjustment(AdjustmentType::Saturation);
    });
    adjustmentMenu->addAction(tr("Invert"), this, [this] {
        addAdjustment(AdjustmentType::Invert);
    });
    adjustmentMenu->addAction(tr("Levels"), this, [this] {
        addAdjustment(AdjustmentType::Levels);
    });
    adjustmentMenu->addAction(tr("Curves"), this, [this] {
        addAdjustment(AdjustmentType::Curves);
    });
    adjustmentMenu->addSeparator();
    adjustmentMenu->addAction(tr("Hue/Saturation"), this, [this] {
        addAdjustment(AdjustmentType::HueSaturation);
    });
    adjustmentMenu->addAction(tr("Vibrance"), this, [this] {
        addAdjustment(AdjustmentType::Vibrance);
    });
    adjustmentMenu->addAction(tr("Photo Filter"), this, [this] {
        addAdjustment(AdjustmentType::PhotoFilter);
    });
    adjustmentMenu->addAction(tr("White Balance"), this, [this] {
        addAdjustment(AdjustmentType::WhiteBalance);
    });
    adjustmentMenu->addAction(tr("Colour Balance"), this, [this] {
        addAdjustment(AdjustmentType::ColourBalance);
    });
    adjustmentMenu->addSeparator();
    adjustmentMenu->addAction(tr("Channel Mixer"), this, [this] {
        addAdjustment(AdjustmentType::ChannelMixer);
    });
    adjustmentMenu->addAction(tr("Black and White"), this, [this] {
        addAdjustment(AdjustmentType::BlackAndWhite);
    });
    adjustmentMenu->addAction(tr("Selective Colour"), this, [this] {
        addAdjustment(AdjustmentType::SelectiveColour);
    });
    adjustmentMenu->addAction(tr("Gradient Map"), this, [this] {
        addAdjustment(AdjustmentType::GradientMap);
    });
    adjustmentMenu->addSeparator();
    adjustmentMenu->addAction(tr("Posterise"), this, [this] {
        addAdjustment(AdjustmentType::Posterise);
    });
    adjustmentMenu->addAction(tr("Threshold"), this, [this] {
        addAdjustment(AdjustmentType::Threshold);
    });
    adjustmentMenu->addAction(tr("LUT…"), this, [this] {
        addAdjustment(AdjustmentType::Lut);
    });
    adjustmentMenu->addAction(tr("Shadows/Highlights"), this, [this] {
        addAdjustment(AdjustmentType::ShadowsHighlights);
    });
    adjustmentMenu->addSeparator();
    QMenu *opticalEffectsMenu = adjustmentMenu->addMenu(tr("Optical and Colour Effects"));
    opticalEffectsMenu->addAction(tr("Vignette"), this, [this] {
        addAdjustment(AdjustmentType::Vignette);
    });
    opticalEffectsMenu->addAction(tr("RGB Split"), this, [this] {
        addAdjustment(AdjustmentType::RgbSplit);
    });
    opticalEffectsMenu->addAction(tr("Chromatic Aberration Correction"), this, [this] {
        addAdjustment(AdjustmentType::ChromaticAberrationCorrection);
    });
    adjustmentMenu->addSeparator();
    QMenu *blurFilterMenu = adjustmentMenu->addMenu(tr("Blur"));
    blurFilterMenu->addAction(tr("Gaussian Blur"), this, [this] {
        addAdjustment(AdjustmentType::GaussianBlur);
    });
    blurFilterMenu->addAction(tr("Box Blur"), this, [this] {
        addAdjustment(AdjustmentType::BoxBlur);
    });
    blurFilterMenu->addAction(tr("Surface Blur"), this, [this] {
        addAdjustment(AdjustmentType::SurfaceBlur);
    });
    blurFilterMenu->addAction(tr("Motion Blur"), this, [this] {
        addAdjustment(AdjustmentType::MotionBlur);
    });
    blurFilterMenu->addAction(tr("Radial Blur"), this, [this] {
        addAdjustment(AdjustmentType::RadialBlur);
    });
    QMenu *sharpenFilterMenu = adjustmentMenu->addMenu(tr("Sharpen"));
    sharpenFilterMenu->addAction(tr("Unsharp Mask"), this, [this] {
        addAdjustment(AdjustmentType::UnsharpMask);
    });
    sharpenFilterMenu->addAction(tr("High Pass"), this, [this] {
        addAdjustment(AdjustmentType::HighPass);
    });
    layerMenu->addAction(m_addMaskAction);
    layerMenu->addAction(m_maskFromSelectionAction);
    layerMenu->addAction(m_removeMaskAction);
    layerMenu->addAction(m_enableMaskAction);
    layerMenu->addAction(m_invertMaskAction);
    layerMenu->addSeparator();
    layerMenu->addAction(m_convertShapeToPathAction);
    layerMenu->addAction(m_expandStrokeAction);
    QMenu *vectorAppearanceLayerMenu = layerMenu->addMenu(tr("Vector Appearance"));
    vectorAppearanceLayerMenu->addAction(m_swapVectorFillStrokeAction);
    vectorAppearanceLayerMenu->addAction(m_resetVectorFillStrokeAction);
    vectorAppearanceLayerMenu->addSeparator();
    vectorAppearanceLayerMenu->addAction(m_copyVectorAppearanceAction);
    vectorAppearanceLayerMenu->addAction(m_pasteVectorAppearanceAction);
    vectorAppearanceLayerMenu->addSeparator();
    vectorAppearanceLayerMenu->addAction(m_vectorAppearancePresetsAction);
    layerMenu->addSeparator();
    layerMenu->addAction(m_convertToSmartLayerAction);
    layerMenu->addAction(m_placeLinkedSmartLayerAction);
    layerMenu->addAction(m_editSmartLayerContentsAction);
    layerMenu->addAction(m_replaceSmartLayerSourceAction);
    layerMenu->addAction(m_relinkSmartLayerSourceAction);
    layerMenu->addAction(m_embedLinkedSmartSourceAction);
    layerMenu->addAction(m_mergeLayersAction);
    layerMenu->addAction(m_duplicateLayerAction);
    layerMenu->addAction(m_removeLayerAction);
    layerMenu->addAction(m_moveLayerUpAction);
    layerMenu->addAction(m_moveLayerDownAction);

    m_viewMenu = menuBar()->addMenu(tr("&View"));
    m_viewMenu->addAction(m_fitAction);
    m_viewMenu->addAction(m_actualPixelsAction);
    m_viewMenu->addSeparator();
    m_viewMenu->addAction(m_showRulersAction);
    m_viewMenu->addAction(m_showGuidesAction);
    m_viewMenu->addAction(m_snapGuidesAction);
    m_viewMenu->addAction(m_clearGuidesAction);
    m_viewMenu->addSeparator();
    m_viewMenu->addAction(m_nextDocumentAction);
    m_viewMenu->addAction(m_previousDocumentAction);
    m_viewMenu->addSeparator();

    QMenu *themeMenu = m_viewMenu->addMenu(tr("Theme"));
    m_themeActionGroup = new QActionGroup(this);
    m_themeActionGroup->setExclusive(true);
    const AppTheme themes[] = {
        AppTheme::Midnight,
        AppTheme::Graphite,
        AppTheme::Daylight,
    };
    for (const AppTheme theme : themes) {
        QAction *action = themeMenu->addAction(applicationThemeName(theme));
        action->setCheckable(true);
        action->setData(applicationThemeId(theme));
        action->setChecked(theme == activeApplicationTheme());
        m_themeActionGroup->addAction(action);
        connect(action, &QAction::triggered, this, [this, action] {
            applyTheme(action->data().toString());
        });
    }

    m_viewMenu->addSeparator();
    m_viewMenu->addAction(m_resetWorkspaceAction);

    QMenu *helpMenu = menuBar()->addMenu(tr("&Help"));
    helpMenu->addAction(tr("About VFX Photo Lab"), this, &MainWindow::showAboutDialog);

    m_toolOptionsBar = new FixedHeightToolBar(tr("Tool Options"), 44, this);
    m_toolOptionsBar->setObjectName(QStringLiteral("ToolOptionsToolbar"));
    m_toolOptionsBar->setMovable(false);
    m_toolOptionsBar->setFloatable(false);
    m_toolOptionsBar->setAllowedAreas(Qt::TopToolBarArea);
    m_toolOptionsBar->setContextMenuPolicy(Qt::PreventContextMenu);
    // The complete toolbar row has one invariant outer height. QMainWindow's
    // toolbar layout can otherwise honour a newly inserted child's size hint
    // for a frame, which visibly jolts the ruler/canvas by one or two pixels.
    m_toolOptionsBar->setFixedHeight(44);
    m_toolOptionsBar->setIconSize(QSize(20, 20));
    addToolBar(Qt::TopToolBarArea, m_toolOptionsBar);
}

void MainWindow::applyTheme(const QString &themeId)
{
    const AppTheme theme = applicationThemeFromId(themeId);
    if (theme == activeApplicationTheme()) {
        return;
    }

    setActiveApplicationTheme(theme);
    QSettings().setValue(QStringLiteral("appearance/theme"), applicationThemeId(theme));
    qApp->setPalette(applicationPalette());
    qApp->setStyleSheet(applicationStyleSheet());

    if (m_themeActionGroup) {
        for (QAction *action : m_themeActionGroup->actions()) {
            const QSignalBlocker blocker(action);
            action->setChecked(action->data().toString() == applicationThemeId(theme));
        }
    }
    refreshThemeDependentUi();
    statusBar()->showMessage(tr("Theme changed to %1").arg(applicationThemeName(theme)), 2500);
}

void MainWindow::refreshThemeDependentUi()
{
    for (const auto &documentSession : m_sessions) {
        if (documentSession) {
            documentSession->thumbnailCache().clear();
        }
    }

    const QColor iconColour = themeColour(QStringLiteral("text"));
    const auto setLayerButtonIcon = [iconColour](QToolButton *button,
                                                  const LayerControlIcon icon) {
        if (button) {
            button->setIcon(layerControlIcon(icon, iconColour));
        }
    };
    setLayerButtonIcon(m_addLayerButton, LayerControlIcon::NewLayer);
    setLayerButtonIcon(m_addGroupButton, LayerControlIcon::NewGroup);
    setLayerButtonIcon(m_addAdjustmentButton, LayerControlIcon::Adjustment);
    setLayerButtonIcon(m_addMaskButton, LayerControlIcon::Mask);
    setLayerButtonIcon(m_duplicateLayerButton, LayerControlIcon::Duplicate);
    setLayerButtonIcon(m_moveLayerUpButton, LayerControlIcon::MoveUp);
    setLayerButtonIcon(m_moveLayerDownButton, LayerControlIcon::MoveDown);
    setLayerButtonIcon(m_removeLayerButton, LayerControlIcon::Remove);
    if (m_colourSwapButton) {
        m_colourSwapButton->setIcon(swapColoursIcon());
    }
    if (m_colourDefaultButton) {
        m_colourDefaultButton->setIcon(defaultColoursIcon());
    }
    if (m_colourEyedropperButton) {
        m_colourEyedropperButton->setIcon(
            themedResourceIcon(QStringLiteral(":/icons/eyedropper.png")));
    }
    if (m_toolActionGroup) {
        for (QAction *action : m_toolActionGroup->actions()) {
            const QString iconPath = action->property("vfxThemeIconPath").toString();
            if (!iconPath.isEmpty()) {
                action->setIcon(themedResourceIcon(iconPath));
            }
        }
    }

    updateColourPanel();
    updateSavedSwatches();
    updateChannelModelUi();
    if (m_activeSession && m_activeSession->document().hasImage()) {
        refreshDocumentUi(session().editTargetLayerId());
    }
    if (m_canvas) {
        m_canvas->update();
        m_canvas->viewport()->update();
    }
    if (m_documentStrip) {
        m_documentStrip->update();
    }
    menuBar()->update();
    update();
}

