void MainWindow::arrangeRightDocks()
{
    splitDockWidget(m_colourDock, m_inspectorDock, Qt::Vertical);
    splitDockWidget(m_inspectorDock, m_layersDock, Qt::Vertical);
    tabifyDockWidget(m_layersDock, m_channelsDock);
    m_layersDock->raise();

    resizeDocks({m_colourDock, m_inspectorDock, m_layersDock},
                {330, 310, 260},
                Qt::Vertical);
    resizeDocks({m_colourDock, m_inspectorDock, m_layersDock},
                {275, 275, 275},
                Qt::Horizontal);

    if (m_viewMenu) {
        m_viewMenu->addSeparator();
        m_viewMenu->addAction(m_toolOptionsBar->toggleViewAction());
        m_viewMenu->addAction(m_toolsToolbar->toggleViewAction());
        m_viewMenu->addSeparator();
        m_viewMenu->addAction(m_colourDock->toggleViewAction());
        m_viewMenu->addAction(m_inspectorDock->toggleViewAction());
        m_viewMenu->addAction(m_channelsDock->toggleViewAction());
        m_viewMenu->addAction(m_layersDock->toggleViewAction());
        m_viewMenu->addAction(m_exportQueueDock->toggleViewAction());
    }
}

void MainWindow::restoreStoredWorkspaceLayout()
{
    QSettings settings;
    const QByteArray geometry = settings.value(QStringLiteral("workspace/geometry")).toByteArray();
    if (!geometry.isEmpty()) {
        restoreGeometry(geometry);
    }

    const QByteArray state = settings.value(QStringLiteral("workspace/state")).toByteArray();
    if (!state.isEmpty() && !restoreState(state, WorkspaceStateVersion)) {
        restoreState(m_defaultWorkspaceState, WorkspaceStateVersion);
    }
}

void MainWindow::saveWorkspaceLayout()
{
    QSettings settings;
    settings.setValue(QStringLiteral("workspace/geometry"), saveGeometry());
    settings.setValue(QStringLiteral("workspace/state"), saveState(WorkspaceStateVersion));
}

void MainWindow::resetWorkspaceLayout()
{
    restoreState(m_defaultWorkspaceState, WorkspaceStateVersion);
    m_toolOptionsBar->show();
    m_toolsToolbar->show();
    m_colourDock->show();
    m_inspectorDock->show();
    m_channelsDock->show();
    m_layersDock->show();
    m_layersDock->raise();
    if (m_colourTabs) {
        m_colourTabs->setCurrentIndex(0);
    }

    QSettings settings;
    settings.remove(QStringLiteral("workspace/state"));
    settings.setValue(QStringLiteral("colours/activeTab"), 0);
    statusBar()->showMessage(tr("Workspace layout restored to its default arrangement."), 4000);
}

void MainWindow::newDocument()
{
    if (documentMutationBusy()) {
        statusBar()->showMessage(tr("Finish the current edit or export before creating another document."), 3000);
        return;
    }

    NewDocumentDialog dialog(m_primaryColour, this);
    if (dialog.exec() != QDialog::Accepted) {
        return;
    }

    QString error;
    PhotoDocument candidate;
    if (!candidate.createNewDocument(dialog.settings(), &error)) {
        QMessageBox::critical(this,
                              tr("Could Not Create Document"),
                              error.isEmpty()
                                  ? tr("The requested document could not be created.")
                                  : error);
        return;
    }

    DocumentSession *target = createDocumentSession();
    if (target != m_activeSession) {
        captureActiveSessionUiState();
        resetPreviewControllerForSessionSwitch();
        if (!setActiveSession(target)) {
            return;
        }
    }
    initialiseActiveDocument(std::move(candidate), true);
}

void MainWindow::showColourManagementPreferences()
{
    QDialog dialog(this);
    dialog.setWindowTitle(tr("Colour Management Preferences"));
    dialog.setModal(true);

    auto *layout = new QVBoxLayout(&dialog);
    auto *description = new QLabel(
        tr("Choose how VFX Photo Lab interprets images that do not contain a usable embedded colour profile. "
           "Opening a file or creating a document assigns an interpretation without rewriting its pixels. "
           "Pasting into an existing differently tagged document may use the existing clipboard profile-conversion path."),
        &dialog);
    description->setWordWrap(true);
    layout->addWidget(description);

    auto *form = new QFormLayout;
    auto *policyCombo = new QComboBox(&dialog);
    policyCombo->addItem(tr("Assume sRGB (recommended)"),
                         static_cast<int>(UntaggedImagePolicy::AssumeSRgb));
    policyCombo->addItem(tr("Ask every time"),
                         static_cast<int>(UntaggedImagePolicy::Ask));
    policyCombo->addItem(tr("Leave untagged"),
                         static_cast<int>(UntaggedImagePolicy::LeaveUntagged));
    const int storedIndex = policyCombo->findData(
        static_cast<int>(storedUntaggedImagePolicy()));
    policyCombo->setCurrentIndex(std::max(0, storedIndex));
    form->addRow(tr("Untagged images"), policyCombo);

    auto *warningCheck = new QCheckBox(
        tr("Show a warning when an embedded profile is damaged or unsupported"),
        &dialog);
    warningCheck->setChecked(QSettings().value(
        QString::fromLatin1(ShowImportWarningsSettingsKey), true).toBool());
    form->addRow(QString(), warningCheck);
    layout->addLayout(form);

    auto *note = new QLabel(
        tr("Assume sRGB is the safest default for ordinary web images, screenshots and clipboard content. "
           "Leave untagged keeps the stored components uninterpreted until a profile is assigned later."),
        &dialog);
    note->setWordWrap(true);
    note->setProperty("class", "muted");
    layout->addWidget(note);

    auto *buttons = new QDialogButtonBox(
        QDialogButtonBox::Ok | QDialogButtonBox::Cancel, &dialog);
    connect(buttons, &QDialogButtonBox::accepted, &dialog, &QDialog::accept);
    connect(buttons, &QDialogButtonBox::rejected, &dialog, &QDialog::reject);
    layout->addWidget(buttons);

    layout->activate();
    dialog.setMinimumSize(dialog.minimumSizeHint().expandedTo(QSize(560, 320)));
    dialog.resize(dialog.sizeHint().expandedTo(QSize(620, 360)));

    if (dialog.exec() != QDialog::Accepted) return;
    storeUntaggedImagePolicy(static_cast<UntaggedImagePolicy>(
        policyCombo->currentData().toInt()));
    QSettings().setValue(QString::fromLatin1(ShowImportWarningsSettingsKey),
                         warningCheck->isChecked());
    statusBar()->showMessage(tr("Colour-management import preferences updated."),
                             2500);
}

bool MainWindow::applyPresentationColourState(
    const DocumentColourState &updatedState,
    QString *errorMessage)
{
    if (!document().hasImage()) return false;
    QString safetyError;
    if (!updatedState.isSafe(&safetyError)) {
        if (errorMessage) *errorMessage = safetyError;
        return false;
    }
    if (!document().replacePresentationColourState(updatedState, errorMessage)) {
        return false;
    }

    // Display/proof changes are persisted metadata but never editing history or
    // processing identity. ImageCanvas invalidates only its derived presentation
    // copies, leaving raster/layer storage and raw renderer caches untouched.
    session().refreshSummary();
    updateDocumentStripEntry(&session());
    updateWindowTitle();
    updateActionStates();
    refreshDisplayColourManagement(true);
    return true;
}

void MainWindow::refreshDisplayColourManagement(const bool force)
{
    if (!m_canvas) return;
    if (!document().hasImage()) {
        m_canvas->setDisplayColourTransform({});
        m_activeMonitorProfile = {};
        m_activeDisplayTransformStatus = {};
        m_displayColourManagementError.clear();
        m_monitorProfileDiscoveryKey.clear();
        return;
    }

    QSettings settings;
    const QString manualOverride = settings.value(
        QStringLiteral("colour/display/manualMonitorProfile")).toString();
    QScreen *screen = windowHandle() ? windowHandle()->screen()
                                     : QGuiApplication::primaryScreen();
    const QString discoveryKey = QStringList{
        screen ? screen->name() : QString(),
        screen ? screen->manufacturer() : QString(),
        screen ? screen->model() : QString(),
        screen ? screen->serialNumber() : QString(),
        manualOverride,
        qEnvironmentVariable("VFXPHOTOLAB_MONITOR_ICC")
    }.join(QLatin1Char('|'));
    MonitorProfileInfo monitor;
    if (!force && discoveryKey == m_monitorProfileDiscoveryKey
        && m_activeMonitorProfile.profile.isValid()) {
        monitor = m_activeMonitorProfile;
    } else {
        monitor = discoverMonitorProfile(screen, manualOverride);
        m_monitorProfileDiscoveryKey = discoveryKey;
    }
    QString error;
    const auto transform = createDisplayColourTransform(
        document().colourState(), monitor, &error);
    if (!transform) {
        m_canvas->setDisplayColourTransform({});
        m_activeMonitorProfile = monitor;
        m_activeDisplayTransformStatus = {};
        m_activeDisplayTransformStatus.summary = tr("Unmanaged fallback");
        m_displayColourManagementError = error;
        if (force && m_documentStrip) refreshDocumentStrip();
    } else {
        const bool changed = force
            || m_canvas->displayColourTransformFingerprint()
                != transform->fingerprint();
        m_activeMonitorProfile = monitor;
        m_activeDisplayTransformStatus = transform->status();
        m_displayColourManagementError = error.isEmpty()
            ? m_activeDisplayTransformStatus.warning : error;
        if (changed) m_canvas->setDisplayColourTransform(transform);
        if ((force || changed) && m_documentStrip) refreshDocumentStrip();
    }
    updateStatusText();
}

void MainWindow::showDisplayColourManagement()
{
    if (!document().hasImage()) return;
    refreshDisplayColourManagement();
    const DocumentColourState currentState = document().colourState();

    QDialog dialog(this);
    dialog.setWindowTitle(tr("Display Colour Management and Soft Proofing"));
    dialog.setModal(true);
    auto *outer = new QVBoxLayout(&dialog);

    auto *compatibilityNote = new QLabel(&dialog);
    compatibilityNote->setWordWrap(true);
    compatibilityNote->setProperty("class", "muted");
    compatibilityNote->setText(currentState.presentationColourManagementEnabled
        ? tr("Display and proof transforms affect canvas presentation only. They do not modify pixels, layers, history, copy/merge operations or exports.")
        : tr("Legacy-compatible presentation is active for this existing project. Enable colour-managed presentation below when you are ready; opening the project alone has not changed its appearance."));
    outer->addWidget(compatibilityNote);

    auto *tabs = new QTabWidget(&dialog);
    outer->addWidget(tabs, 1);

    QWidget *displayPage = new QWidget(tabs);
    auto *displayLayout = new QVBoxLayout(displayPage);
    auto *enablePresentation = new QCheckBox(
        tr("Enable colour-managed canvas presentation for this document"), displayPage);
    enablePresentation->setChecked(currentState.presentationColourManagementEnabled);
    displayLayout->addWidget(enablePresentation);

    auto *monitorGroup = new QGroupBox(tr("Active monitor"), displayPage);
    auto *monitorForm = new QFormLayout(monitorGroup);
    auto *screenValue = new QLabel(m_activeMonitorProfile.screenName, monitorGroup);
    auto *monitorValue = new QLabel(m_activeMonitorProfile.profile.displayName, monitorGroup);
    auto *monitorSource = new QLabel(m_activeMonitorProfile.sourceLabel, monitorGroup);
    auto *monitorStatus = new QLabel(m_activeMonitorProfile.status, monitorGroup);
    monitorStatus->setWordWrap(true);
    monitorForm->addRow(tr("Screen"), screenValue);
    monitorForm->addRow(tr("Profile"), monitorValue);
    monitorForm->addRow(tr("Source"), monitorSource);
    monitorForm->addRow(tr("Status"), monitorStatus);

    QSettings settings;
    auto *manualMonitorPath = new QLineEdit(
        settings.value(QStringLiteral("colour/display/manualMonitorProfile")).toString(),
        monitorGroup);
    manualMonitorPath->setPlaceholderText(tr("Automatic discovery through colord or Windows Color System"));
    auto *manualRow = new QWidget(monitorGroup);
    auto *manualRowLayout = new QHBoxLayout(manualRow);
    manualRowLayout->setContentsMargins(0, 0, 0, 0);
    manualRowLayout->addWidget(manualMonitorPath, 1);
    auto *browseMonitor = new QPushButton(tr("Browse…"), manualRow);
    auto *clearMonitor = new QPushButton(tr("Automatic"), manualRow);
    manualRowLayout->addWidget(browseMonitor);
    manualRowLayout->addWidget(clearMonitor);
    monitorForm->addRow(tr("Manual override"), manualRow);
    connect(browseMonitor, &QPushButton::clicked, &dialog, [this, manualMonitorPath] {
        const QString path = QFileDialog::getOpenFileName(
            this, tr("Choose Monitor ICC Profile"), manualMonitorPath->text(),
            tr("ICC profiles (*.icc *.icm);;All files (*)"));
        if (!path.isEmpty()) manualMonitorPath->setText(path);
    });
    connect(clearMonitor, &QPushButton::clicked, manualMonitorPath, &QLineEdit::clear);
    displayLayout->addWidget(monitorGroup);

    auto *renderGroup = new QGroupBox(tr("Document presentation transform"), displayPage);
    auto *renderForm = new QFormLayout(renderGroup);
    auto *displayKind = new QComboBox(renderGroup);
    displayKind->addItem(tr("Automatic monitor ICC profile"),
                         static_cast<int>(DisplayTransformKind::SystemIcc));
    displayKind->addItem(tr("Specific document display ICC profile"),
                         static_cast<int>(DisplayTransformKind::IccProfile));
    displayKind->addItem(tr("OpenColorIO Display / View"),
                         static_cast<int>(DisplayTransformKind::OcioView));
    int kindIndex = displayKind->findData(static_cast<int>(currentState.displayTransform.kind));
    if (kindIndex < 0) kindIndex = 0;
    displayKind->setCurrentIndex(kindIndex);
    renderForm->addRow(tr("Renderer"), displayKind);
    auto *presentationBackend = new QLabel(
        RenderBackend::instance().webGpuDisplayTransformParityPassed()
            ? tr("Validated WGSL GPU path (CPU reference fallback remains available)")
            : tr("CPU reference path (GPU unavailable, uninitialised or parity-rejected)"),
        renderGroup);
    presentationBackend->setWordWrap(true);
    presentationBackend->setProperty("class", "muted");
    renderForm->addRow(tr("Processing backend"), presentationBackend);

    ColourSpaceDescriptor selectedDisplayIcc = currentState.displayTransform.profile;
    auto *displayIccValue = new QLineEdit(renderGroup);
    displayIccValue->setReadOnly(true);
    displayIccValue->setText(selectedDisplayIcc.isUntagged()
        ? tr("No profile selected")
        : selectedDisplayIcc.displayName);
    auto *displayIccRow = new QWidget(renderGroup);
    auto *displayIccLayout = new QHBoxLayout(displayIccRow);
    displayIccLayout->setContentsMargins(0, 0, 0, 0);
    displayIccLayout->addWidget(displayIccValue, 1);
    auto *browseDisplayIcc = new QPushButton(tr("Choose…"), displayIccRow);
    displayIccLayout->addWidget(browseDisplayIcc);
    renderForm->addRow(tr("Display ICC"), displayIccRow);
    connect(browseDisplayIcc, &QPushButton::clicked, &dialog,
            [this, &selectedDisplayIcc, displayIccValue] {
        const QString path = QFileDialog::getOpenFileName(
            this, tr("Choose Display ICC Profile"), selectedDisplayIcc.externalPath,
            tr("ICC profiles (*.icc *.icm);;All files (*)"));
        if (path.isEmpty()) return;
        QString error;
        ColourSpaceDescriptor descriptor;
        if (!loadExternalIccProfile(path, &descriptor, &error)) {
            QMessageBox::warning(this, tr("Invalid ICC Profile"), error);
            return;
        }
        selectedDisplayIcc = descriptor;
        displayIccValue->setText(descriptor.displayName);
    });

    OcioConfigInspection ocioInspection;
    QString ocioError;
    const bool ocioAvailable = currentState.ocioConfig.isConfigured()
        && resolveOcioConfiguration(currentState.ocioConfig,
                                    &ocioInspection, &ocioError)
        && ocioInspection.available
        && ocioInspection.fingerprintMatchesSavedReference;
    auto *ocioDisplay = new QComboBox(renderGroup);
    auto *ocioView = new QComboBox(renderGroup);
    auto *ocioLook = new QComboBox(renderGroup);
    if (ocioAvailable) {
        for (const OcioDisplayInfo &info : ocioInspection.displays) {
            ocioDisplay->addItem(info.name, info.name);
        }
        ocioLook->addItem(tr("Configuration default / none"), QString());
        for (const QString &look : ocioInspection.looks) ocioLook->addItem(look, look);
        int displayIndex = ocioDisplay->findData(currentState.displayTransform.ocioDisplay);
        if (displayIndex < 0) displayIndex = ocioDisplay->findData(ocioInspection.defaultDisplay);
        if (displayIndex >= 0) ocioDisplay->setCurrentIndex(displayIndex);
        int lookIndex = ocioLook->findData(currentState.displayTransform.ocioLook);
        if (lookIndex >= 0) ocioLook->setCurrentIndex(lookIndex);
    } else {
        ocioDisplay->addItem(tr("No fingerprint-matched OCIO configuration"));
        ocioDisplay->setEnabled(false);
        ocioView->setEnabled(false);
        ocioLook->setEnabled(false);
    }
    const auto rebuildOcioViews = [=, &ocioInspection] {
        ocioView->clear();
        if (!ocioAvailable) return;
        const QString display = ocioDisplay->currentData().toString();
        const auto found = std::find_if(
            ocioInspection.displays.cbegin(), ocioInspection.displays.cend(),
            [&](const OcioDisplayInfo &info) { return info.name == display; });
        if (found == ocioInspection.displays.cend()) return;
        for (const QString &view : found->views) ocioView->addItem(view, view);
        int index = ocioView->findData(currentState.displayTransform.ocioView);
        if (index < 0) index = ocioView->findData(found->defaultView);
        if (index >= 0) ocioView->setCurrentIndex(index);
    };
    connect(ocioDisplay, &QComboBox::currentIndexChanged,
            &dialog, [rebuildOcioViews](int) { rebuildOcioViews(); });
    rebuildOcioViews();
    renderForm->addRow(tr("OCIO display"), ocioDisplay);
    renderForm->addRow(tr("OCIO view"), ocioView);
    renderForm->addRow(tr("OCIO look"), ocioLook);

    auto *missingOcio = new QLabel(ocioAvailable ? QString() : ocioError, renderGroup);
    missingOcio->setWordWrap(true);
    missingOcio->setProperty("class", "muted");
    renderForm->addRow(QString(), missingOcio);
    displayLayout->addWidget(renderGroup);
    displayLayout->addStretch(1);
    tabs->addTab(displayPage, tr("Display"));

    QWidget *proofPage = new QWidget(tabs);
    auto *proofLayout = new QVBoxLayout(proofPage);
    auto *proofEnabled = new QCheckBox(tr("Enable soft proofing"), proofPage);
    proofEnabled->setChecked(currentState.proofing.enabled);
    proofLayout->addWidget(proofEnabled);
    auto *proofGroup = new QGroupBox(tr("Output simulation"), proofPage);
    auto *proofForm = new QFormLayout(proofGroup);
    ColourSpaceDescriptor selectedProof = currentState.proofing.profile;
    auto *proofValue = new QLineEdit(proofGroup);
    proofValue->setReadOnly(true);
    proofValue->setText(selectedProof.isUntagged()
        ? tr("No proof profile selected") : selectedProof.displayName);
    auto *proofRow = new QWidget(proofGroup);
    auto *proofRowLayout = new QHBoxLayout(proofRow);
    proofRowLayout->setContentsMargins(0, 0, 0, 0);
    proofRowLayout->addWidget(proofValue, 1);
    auto *browseProof = new QPushButton(tr("Choose…"), proofRow);
    proofRowLayout->addWidget(browseProof);
    proofForm->addRow(tr("Proof ICC profile"), proofRow);
    connect(browseProof, &QPushButton::clicked, &dialog,
            [this, &selectedProof, proofValue] {
        const QString path = QFileDialog::getOpenFileName(
            this, tr("Choose Proof ICC Profile"), selectedProof.externalPath,
            tr("ICC profiles (*.icc *.icm);;All files (*)"));
        if (path.isEmpty()) return;
        QString error;
        ColourSpaceDescriptor descriptor;
        if (!loadExternalIccProfile(path, &descriptor, &error)) {
            QMessageBox::warning(this, tr("Invalid ICC Profile"), error);
            return;
        }
        selectedProof = descriptor;
        proofValue->setText(descriptor.displayName);
    });

    auto *intent = new QComboBox(proofGroup);
    for (const ColourRenderingIntent value : {
             ColourRenderingIntent::Perceptual,
             ColourRenderingIntent::RelativeColorimetric,
             ColourRenderingIntent::Saturation,
             ColourRenderingIntent::AbsoluteColorimetric}) {
        intent->addItem(colourRenderingIntentName(value), static_cast<int>(value));
    }
    intent->setCurrentIndex(std::max(0, intent->findData(
        static_cast<int>(currentState.proofing.renderingIntent))));
    proofForm->addRow(tr("Rendering intent"), intent);
    auto *blackPoint = new QCheckBox(tr("Request black-point compensation"), proofGroup);
    blackPoint->setChecked(currentState.proofing.blackPointCompensation);
    proofForm->addRow(QString(), blackPoint);
    auto *gamutWarning = new QCheckBox(
        tr("Highlight approximate out-of-gamut colours in magenta"), proofGroup);
    gamutWarning->setChecked(currentState.proofing.gamutWarning);
    proofForm->addRow(QString(), gamutWarning);
    auto *proofNote = new QLabel(
        tr("The CPU reference defines the selected intent and black-point-compensation request. When runtime parity passes, a reference-baked half-float lattice is evaluated by WGSL; unsupported or rejected transforms use the CPU path. Qt applies the available ICC transform, so support for intent and BPC depends on the active profile engine. Gamut warning is a deterministic round-trip approximation."),
        proofGroup);
    proofNote->setWordWrap(true);
    proofNote->setProperty("class", "muted");
    proofForm->addRow(QString(), proofNote);
    proofLayout->addWidget(proofGroup);
    proofLayout->addStretch(1);
    tabs->addTab(proofPage, tr("Soft Proof"));

    const auto refreshEnabledControls = [=] {
        const bool enabled = enablePresentation->isChecked();
        const DisplayTransformKind kind = static_cast<DisplayTransformKind>(
            displayKind->currentData().toInt());
        monitorGroup->setEnabled(enabled);
        renderGroup->setEnabled(enabled);
        displayIccRow->setEnabled(enabled && kind == DisplayTransformKind::IccProfile);
        ocioDisplay->setEnabled(enabled && ocioAvailable
                                && kind == DisplayTransformKind::OcioView);
        ocioView->setEnabled(enabled && ocioAvailable
                             && kind == DisplayTransformKind::OcioView);
        ocioLook->setEnabled(enabled && ocioAvailable
                             && kind == DisplayTransformKind::OcioView);
        proofEnabled->setEnabled(enabled);
        proofGroup->setEnabled(enabled && proofEnabled->isChecked());
    };
    connect(enablePresentation, &QCheckBox::toggled,
            &dialog, [refreshEnabledControls](bool) { refreshEnabledControls(); });
    connect(proofEnabled, &QCheckBox::toggled,
            &dialog, [refreshEnabledControls](bool) { refreshEnabledControls(); });
    connect(displayKind, &QComboBox::currentIndexChanged,
            &dialog, [refreshEnabledControls](int) { refreshEnabledControls(); });
    refreshEnabledControls();

    auto *buttons = new QDialogButtonBox(
        QDialogButtonBox::Ok | QDialogButtonBox::Cancel, &dialog);
    buttons->button(QDialogButtonBox::Ok)->setText(tr("Apply Presentation Settings"));
    connect(buttons, &QDialogButtonBox::accepted, &dialog, &QDialog::accept);
    connect(buttons, &QDialogButtonBox::rejected, &dialog, &QDialog::reject);
    outer->addWidget(buttons);

    outer->activate();
    dialog.setMinimumSize(dialog.minimumSizeHint().expandedTo(QSize(780, 580)));
    dialog.resize(dialog.sizeHint().expandedTo(QSize(900, 700)));
    if (dialog.exec() != QDialog::Accepted) return;

    const QString monitorOverride = manualMonitorPath->text().trimmed();
    if (!monitorOverride.isEmpty()) {
        ColourSpaceDescriptor ignored;
        QString error;
        if (!loadExternalIccProfile(monitorOverride, &ignored, &error)) {
            QMessageBox::warning(this, tr("Invalid Monitor Profile"), error);
            return;
        }
    }
    DocumentColourState updated = currentState;
    updated.presentationColourManagementEnabled = enablePresentation->isChecked();
    if (updated.presentationColourManagementEnabled) {
        updated.displayTransform.kind = static_cast<DisplayTransformKind>(
            displayKind->currentData().toInt());
        if (updated.displayTransform.kind == DisplayTransformKind::SystemIcc) {
            updated.displayTransform.profile = ColourSpaceDescriptor::untagged();
            updated.displayTransform.ocioConfigId.clear();
            updated.displayTransform.ocioConfigFingerprint.clear();
            updated.displayTransform.ocioDisplay.clear();
            updated.displayTransform.ocioView.clear();
            updated.displayTransform.ocioLook.clear();
        } else if (updated.displayTransform.kind == DisplayTransformKind::IccProfile) {
            if (selectedDisplayIcc.isUntagged()
                || !selectedDisplayIcc.toQColorSpace().isValid()) {
                QMessageBox::warning(this, tr("Display Profile Required"),
                                     tr("Choose a valid display ICC profile."));
                return;
            }
            updated.displayTransform.profile = selectedDisplayIcc;
            updated.displayTransform.ocioConfigId.clear();
            updated.displayTransform.ocioConfigFingerprint.clear();
            updated.displayTransform.ocioDisplay.clear();
            updated.displayTransform.ocioView.clear();
            updated.displayTransform.ocioLook.clear();
        } else if (updated.displayTransform.kind == DisplayTransformKind::OcioView) {
            if (!ocioAvailable || ocioDisplay->currentData().toString().isEmpty()
                || ocioView->currentData().toString().isEmpty()) {
                QMessageBox::warning(this, tr("OCIO Display/View Required"),
                                     tr("Relink a fingerprint-matched OCIO configuration and choose a valid display and view."));
                return;
            }
            const QString display = ocioDisplay->currentData().toString();
            const QString view = ocioView->currentData().toString();
            const QString look = ocioLook->currentData().toString();
            const QString sourceSpace = updated.workingSpace.kind == ColourSpaceKind::Ocio
                ? updated.workingSpace.ocioSpace : ocioInspection.defaultWorkingSpace;
            QString error;
            if (!validateOcioDisplayView(updated.ocioConfig, sourceSpace,
                                         display, view, look, &error)) {
                QMessageBox::warning(this, tr("Invalid OCIO Display/View"), error);
                return;
            }
            updated.displayTransform.profile = ColourSpaceDescriptor::untagged();
            updated.displayTransform.ocioConfigId = updated.ocioConfig.identifier;
            updated.displayTransform.ocioConfigFingerprint = updated.ocioConfig.fingerprint;
            updated.displayTransform.ocioDisplay = display;
            updated.displayTransform.ocioView = view;
            updated.displayTransform.ocioLook = look;
        }

        updated.proofing.enabled = proofEnabled->isChecked();
        if (updated.proofing.enabled) {
            if (selectedProof.isUntagged() || !selectedProof.toQColorSpace().isValid()) {
                QMessageBox::warning(this, tr("Proof Profile Required"),
                                     tr("Choose a valid ICC proof profile."));
                return;
            }
            updated.proofing.profile = selectedProof;
        }
        updated.proofing.renderingIntent = static_cast<ColourRenderingIntent>(
            intent->currentData().toInt());
        updated.proofing.blackPointCompensation = blackPoint->isChecked();
        updated.proofing.gamutWarning = gamutWarning->isChecked();
    }

    settings.setValue(QStringLiteral("colour/display/manualMonitorProfile"),
                      monitorOverride);
    if (updated.semanticallyEquals(currentState)) {
        refreshDisplayColourManagement(true);
        statusBar()->showMessage(
            tr("Monitor presentation refreshed without changing document pixels or history."),
            5000);
        return;
    }

    QString error;
    if (!applyPresentationColourState(updated, &error)) {
        QMessageBox::critical(this, tr("Could Not Apply Display Settings"), error);
        return;
    }
    statusBar()->showMessage(
        tr("Display colour management updated without changing document pixels or history."),
        5000);
}

void MainWindow::configureOpenColorIO()
{
    if (!document().hasImage() || documentMutationBusy()) return;

    const DocumentColourState currentState = document().colourState();
    const QVector<OcioBuiltInConfigChoice> builtIns = ocioBuiltInConfigChoices();
    QStringList choices;
    choices << tr("Disabled (ICC-only document)");
    for (const OcioBuiltInConfigChoice &choice : builtIns) {
        choices << choice.label;
    }
    choices << tr("Use OCIO environment variable")
            << tr("Choose external .ocio or .ocioz file…");

    int initialIndex = 0;
    if (currentState.ocioConfig.source == OcioConfigSource::BuiltIn) {
        for (int index = 0; index < builtIns.size(); ++index) {
            if (currentState.ocioConfig.identifier.contains(
                    builtIns.at(index).uri.mid(QStringLiteral("ocio://").size()),
                    Qt::CaseInsensitive)) {
                initialIndex = index + 1;
                break;
            }
        }
    } else if (currentState.ocioConfig.source == OcioConfigSource::Environment) {
        initialIndex = 1 + builtIns.size();
    } else if (currentState.ocioConfig.source == OcioConfigSource::ExternalFile) {
        initialIndex = 2 + builtIns.size();
    }

    bool accepted = false;
    const QString selected = QInputDialog::getItem(
        this,
        tr("OpenColorIO / ACES Configuration"),
        tr("Select the configuration to associate with this document:"),
        choices,
        initialIndex,
        false,
        &accepted);
    if (!accepted) return;

    const int selectedIndex = choices.indexOf(selected);
    if (selectedIndex == 0) {
        const bool ocioStillReferenced =
            currentState.workingSpace.kind == ColourSpaceKind::Ocio
            || currentState.output.profile.kind == ColourSpaceKind::Ocio
            || currentState.proofing.profile.kind == ColourSpaceKind::Ocio
            || currentState.displayTransform.kind == DisplayTransformKind::OcioView;
        if (ocioStillReferenced) {
            QMessageBox::information(
                this,
                tr("OCIO Is Still In Use"),
                tr("This document still uses an OCIO working, proof, output, or display space. Convert those selections to ICC profiles and disable the OCIO display/view before removing the configuration."));
            return;
        }
        if (!currentState.ocioConfig.isConfigured()) {
            statusBar()->showMessage(tr("OpenColorIO is already disabled for this document."), 3000);
            return;
        }

        const DocumentState before = captureDocumentState();
        DocumentColourState updated = currentState;
        if (updated.inputProfile.kind == ColourSpaceKind::Ocio) {
            updated.inputProfile = ColourSpaceDescriptor::untagged();
            updated.inputProfileStatus = InputProfileStatus::LegacyUnknown;
        }
        updated.ocioConfig = OcioConfigReference::disabled();
        if (updated.displayTransform.kind == DisplayTransformKind::OcioView) {
            updated.displayTransform = {};
            updated.displayTransform.kind = DisplayTransformKind::Disabled;
            updated.displayTransform.profile = ColourSpaceDescriptor::untagged();
        }
        updated.revision = updated.revision == std::numeric_limits<quint64>::max()
            ? updated.revision : updated.revision + 1;
        QString error;
        if (!document().replaceStructuralState(
                before.canvasImage, before.layers, before.selection,
                before.horizontalGuides, before.verticalGuides,
                before.resolutionX, before.resolutionY, updated, &error)) {
            QMessageBox::critical(this, tr("Could Not Disable OpenColorIO"), error);
            return;
        }
        session().advanceRenderSerial();
        RenderBackend::instance().resetSessionState(renderSessionContext());
        const DocumentState after = captureDocumentState();
        const QVector<QUuid> selection = selectedLayerIds();
        recordDocumentChange(tr("Disable OpenColorIO"), before, after,
                             selection, selection);
        updateActionStates();
        updateWindowTitle();
        updateStatusText();
        session().refreshSummary();
        updateDocumentStripEntry(&session());
        schedulePreviewRender();
        scheduleDocumentThumbnail();
        statusBar()->showMessage(tr("OpenColorIO disabled for this document."), 4000);
        return;
    }

    if (!ocioSupportCompiled()) {
        QMessageBox::information(
            this,
            tr("OpenColorIO Is Not Available"),
            tr("This build was created without OpenColorIO. Run ./run.sh again with network access, install OpenColorIO 2.5 development files, or run scripts/fetch-opencolorio.sh, then rebuild."));
        return;
    }

    OcioConfigSource source = OcioConfigSource::None;
    QString locator;
    if (selectedIndex >= 1 && selectedIndex <= builtIns.size()) {
        source = OcioConfigSource::BuiltIn;
        locator = builtIns.at(selectedIndex - 1).uri;
    } else if (selectedIndex == 1 + builtIns.size()) {
        source = OcioConfigSource::Environment;
    } else {
        source = OcioConfigSource::ExternalFile;
        locator = QFileDialog::getOpenFileName(
            this,
            tr("Choose OpenColorIO Configuration"),
            currentState.ocioConfig.canonicalPath,
            tr("OpenColorIO Configurations (*.ocio *.ocioz);;All Files (*)"));
        if (locator.isEmpty()) return;
    }

    OcioConfigInspection inspection;
    QString error;
    if (!inspectOcioConfiguration(source, locator, &inspection, &error)) {
        QMessageBox::warning(
            this,
            tr("Could Not Load OpenColorIO Configuration"),
            error.isEmpty() ? tr("The selected configuration could not be loaded.") : error);
        return;
    }

    QDialog dialog(this);
    dialog.setWindowTitle(tr("OpenColorIO / ACES Settings"));
    dialog.setModal(true);
    auto *layout = new QVBoxLayout(&dialog);
    auto *description = new QLabel(
        tr("This associates a validated OCIO configuration with the document. It does not convert pixels by itself. After activation, use Assign Profile or Convert to Profile to choose an OCIO working space. The display, view and look controls below are for inspection only; presentation choices are stored separately in Display Colour Management and Soft Proofing."),
        &dialog);
    description->setWordWrap(true);
    layout->addWidget(description);

    auto *form = new QFormLayout;
    const auto addValue = [&](const QString &label, const QString &value) {
        auto *field = new QLabel(value, &dialog);
        field->setWordWrap(true);
        field->setTextInteractionFlags(Qt::TextSelectableByMouse);
        form->addRow(label, field);
    };
    addValue(tr("Configuration"), inspection.reference.displayName);
    addValue(tr("Source"), ocioConfigSourceName(inspection.reference.source));
    addValue(tr("Config / library version"), inspection.reference.version);
    addValue(tr("Fingerprint"), shortenedFingerprint(inspection.reference.fingerprint));
    addValue(tr("Available colour spaces"), QString::number(inspection.colourSpaces.size()));

    auto *displayCombo = new QComboBox(&dialog);
    for (const OcioDisplayInfo &display : inspection.displays) {
        displayCombo->addItem(display.name);
    }
    const int defaultDisplayIndex = displayCombo->findText(inspection.defaultDisplay);
    displayCombo->setCurrentIndex(defaultDisplayIndex >= 0 ? defaultDisplayIndex : 0);
    form->addRow(tr("Inspect display"), displayCombo);

    auto *viewCombo = new QComboBox(&dialog);
    form->addRow(tr("Inspect view"), viewCombo);
    const auto rebuildViews = [&] {
        viewCombo->clear();
        const QString display = displayCombo->currentText();
        const auto found = std::find_if(
            inspection.displays.cbegin(), inspection.displays.cend(),
            [&](const OcioDisplayInfo &candidate) {
                return candidate.name == display;
            });
        if (found == inspection.displays.cend()) return;
        viewCombo->addItems(found->views);
        const int defaultViewIndex = viewCombo->findText(found->defaultView);
        viewCombo->setCurrentIndex(defaultViewIndex >= 0 ? defaultViewIndex : 0);
    };
    connect(displayCombo, &QComboBox::currentTextChanged, &dialog,
            [rebuildViews](const QString &) { rebuildViews(); });
    rebuildViews();

    auto *lookCombo = new QComboBox(&dialog);
    lookCombo->addItem(tr("Configuration default / none"), QString());
    for (const QString &look : inspection.looks) lookCombo->addItem(look, look);
    form->addRow(tr("Inspect look"), lookCombo);

    auto *displayNote = new QLabel(
        tr("Selections in these inspection controls are not saved. Choose the active OCIO Display/View in Display Colour Management and Soft Proofing, where presentation changes never create an Undo operation."),
        &dialog);
    displayNote->setWordWrap(true);
    displayNote->setProperty("class", "muted");
    form->addRow(QString(), displayNote);
    layout->addLayout(form);

    auto *rangeNote = new QLabel(
        tr("Current documents use integer RGBA storage. ACEScg and ACES2065-1 conversions are supported within the 0–1 document range; negative and above-1 scene-linear values remain deferred until floating-point document storage."),
        &dialog);
    rangeNote->setWordWrap(true);
    rangeNote->setProperty("class", "muted");
    layout->addWidget(rangeNote);

    auto *buttons = new QDialogButtonBox(
        QDialogButtonBox::Ok | QDialogButtonBox::Cancel, &dialog);
    buttons->button(QDialogButtonBox::Ok)->setText(tr("Use Configuration"));
    connect(buttons, &QDialogButtonBox::accepted, &dialog, &QDialog::accept);
    connect(buttons, &QDialogButtonBox::rejected, &dialog, &QDialog::reject);
    layout->addWidget(buttons);

    layout->activate();
    dialog.setMinimumSize(dialog.minimumSizeHint().expandedTo(QSize(720, 460)));
    dialog.resize(dialog.sizeHint().expandedTo(QSize(830, 540)));

    if (dialog.exec() != QDialog::Accepted) return;

    if (currentState.ocioConfig.isConfigured()
        && currentState.ocioConfig.fingerprint != inspection.reference.fingerprint) {
        const auto decision = QMessageBox::warning(
            this,
            tr("Use a Different OCIO Configuration?"),
            tr("The selected configuration is not identical to the one currently associated with this document. This is an explicit relink and may change future OCIO conversions or display results. Pixels are not changed now."),
            QMessageBox::Ok | QMessageBox::Cancel,
            QMessageBox::Cancel);
        if (decision != QMessageBox::Ok) return;
        if (currentState.displayTransform.kind == DisplayTransformKind::OcioView) {
            QMessageBox::information(
                this,
                tr("Change Display Renderer First"),
                tr("This document currently uses an OCIO Display/View from the existing configuration. Switch the document to Automatic Monitor ICC in Display Colour Management first, then relink the OCIO configuration. This keeps configuration history separate from presentation-only changes."));
            return;
        }
    }

    const DocumentState before = captureDocumentState();
    DocumentColourState updated = currentState;
    updated.ocioConfig = inspection.reference;
    if (updated.displayTransform.kind == DisplayTransformKind::OcioView) {
        // Identical configurations may be relinked from a different path or
        // source identifier without changing the selected Display/View. Keep
        // the presentation reference structurally aligned with the document.
        updated.displayTransform.ocioConfigId = inspection.reference.identifier;
        updated.displayTransform.ocioConfigFingerprint =
            inspection.reference.fingerprint;
    }
    const auto relinkDescriptor = [&](ColourSpaceDescriptor *descriptor) {
        if (!descriptor || descriptor->kind != ColourSpaceKind::Ocio) return true;
        const bool exists = std::any_of(
            inspection.colourSpaces.cbegin(), inspection.colourSpaces.cend(),
            [&](const OcioColourSpaceInfo &space) {
                return !space.data && space.name == descriptor->ocioSpace;
            });
        if (!exists) return false;
        descriptor->ocioConfigId = inspection.reference.identifier;
        descriptor->ocioConfigFingerprint = inspection.reference.fingerprint;
        return true;
    };
    if (!relinkDescriptor(&updated.workingSpace)
        || !relinkDescriptor(&updated.inputProfile)
        || !relinkDescriptor(&updated.proofing.profile)
        || !relinkDescriptor(&updated.output.profile)) {
        QMessageBox::warning(
            this,
            tr("OCIO Space Missing"),
            tr("The new configuration does not contain one of the OCIO colour spaces used by this document. Convert the document to an ICC working profile before switching configurations."));
        return;
    }

    updated.revision = updated.revision == std::numeric_limits<quint64>::max()
        ? updated.revision : updated.revision + 1;

    if (!document().replaceStructuralState(
            before.canvasImage, before.layers, before.selection,
            before.horizontalGuides, before.verticalGuides,
            before.resolutionX, before.resolutionY, updated, &error)) {
        QMessageBox::critical(this, tr("Could Not Apply OpenColorIO Settings"), error);
        return;
    }
    session().advanceRenderSerial();
    RenderBackend::instance().resetSessionState(renderSessionContext());
    const DocumentState after = captureDocumentState();
    const QVector<QUuid> selection = selectedLayerIds();
    recordDocumentChange(tr("OpenColorIO Settings — %1")
                             .arg(inspection.reference.displayName),
                         before, after, selection, selection);
    updateActionStates();
    updateWindowTitle();
    refreshDisplayColourManagement();
    updateStatusText();
    session().refreshSummary();
    updateDocumentStripEntry(&session());
    schedulePreviewRender();
    scheduleDocumentThumbnail();
    statusBar()->showMessage(
        tr("OpenColorIO configuration activated. Use Assign/Convert for working spaces and Display Colour Management for Display/View presentation."),
        6500);
}

void MainWindow::showDocumentColourInformation()
{
    if (!document().hasImage()) return;
    refreshDisplayColourManagement();
    const DocumentColourState &state = document().colourState();
    const ColourResourceAuditReport resourceAudit =
        auditDocumentColourResources(state);

    QDialog dialog(this);
    dialog.setWindowTitle(tr("Document Colour Information"));
    dialog.setModal(true);
    auto *layout = new QVBoxLayout(&dialog);
    auto *form = new QFormLayout;
    form->setFieldGrowthPolicy(QFormLayout::AllNonFixedFieldsGrow);

    const auto addValue = [&](const QString &label, const QString &value,
                              const QString &toolTip = QString()) {
        auto *field = new QLabel(value, &dialog);
        field->setTextInteractionFlags(Qt::TextSelectableByMouse);
        field->setWordWrap(true);
        if (!toolTip.isEmpty()) field->setToolTip(toolTip);
        form->addRow(label, field);
    };

    addValue(tr("Input status"), inputProfileStatusName(state.inputProfileStatus));
    addValue(tr("Input interpretation"),
             state.inputProfile.displayName.isEmpty()
                 ? tr("Untagged") : state.inputProfile.displayName);
    addValue(tr("Working space"),
             state.workingSpace.displayName.isEmpty()
                 ? tr("Untagged") : state.workingSpace.displayName);
    addValue(tr("Untagged handling"),
             state.untaggedPolicyApplied
                 ? untaggedImagePolicyName(state.untaggedPolicy)
                 : tr("Not applied"));
    const QString fullFingerprint = state.originalInputProfileFingerprint.isEmpty()
        ? QString() : QString::fromLatin1(
              state.originalInputProfileFingerprint.toHex());
    addValue(tr("Original profile fingerprint"),
             shortenedFingerprint(state.originalInputProfileFingerprint),
             fullFingerprint);
    addValue(tr("Embedded ICC data"),
             state.inputProfile.iccProfile.isEmpty()
                 ? tr("Not stored")
                 : tr("%1 bytes preserved").arg(state.inputProfile.iccProfile.size()));
    addValue(tr("Processing compatibility"),
             colourProcessingCompatibilityName(state.processingCompatibility));
    addValue(tr("Managed presentation"),
             state.presentationColourManagementEnabled ? tr("Enabled")
                                                       : tr("Inactive (legacy protection)"));
    addValue(tr("Display transform"),
             displayTransformKindName(state.displayTransform.kind));
    addValue(tr("Active screen"),
             m_activeMonitorProfile.screenName.isEmpty()
                 ? tr("Unknown") : m_activeMonitorProfile.screenName);
    addValue(tr("Monitor profile"),
             m_activeMonitorProfile.profile.displayName.isEmpty()
                 ? tr("sRGB fallback") : m_activeMonitorProfile.profile.displayName);
    addValue(tr("Monitor profile source"),
             m_activeMonitorProfile.sourceLabel.isEmpty()
                 ? tr("Not resolved") : m_activeMonitorProfile.sourceLabel);
    addValue(tr("Active presentation"),
             m_activeDisplayTransformStatus.summary.isEmpty()
                 ? tr("Unmanaged") : m_activeDisplayTransformStatus.summary);
    addValue(tr("Presentation backend"),
             RenderBackend::instance().webGpuDisplayTransformParityPassed()
                 ? tr("Validated WGSL GPU with CPU reference fallback")
                 : tr("CPU reference"));
    if (!m_displayColourManagementError.isEmpty()) {
        addValue(tr("Presentation warning"), m_displayColourManagementError);
    }
    addValue(tr("Soft proof"),
             state.proofing.enabled
                 ? tr("%1 — %2%3")
                       .arg(state.proofing.profile.displayName,
                            colourRenderingIntentName(state.proofing.renderingIntent),
                            state.proofing.gamutWarning
                                ? tr(" — gamut warning") : QString())
                 : tr("Disabled"));
    addValue(tr("Saved export output profile"),
             state.output.profile.displayName.trimmed().isEmpty()
                 ? tr("Untagged") : state.output.profile.displayName);
    addValue(tr("Saved export intent"),
             colourRenderingIntentName(state.output.renderingIntent));
    addValue(tr("Export black-point compensation"),
             state.output.blackPointCompensation ? tr("Requested")
                                                  : tr("Disabled"));
    addValue(tr("Export ICC embedding preference"),
             state.output.embedProfile ? tr("Enabled where supported")
                                       : tr("Disabled"));
    addValue(tr("Colour resource status"), resourceAudit.summary());
    if (!resourceAudit.isHealthy()) {
        addValue(tr("Colour resource details"),
                 QStringLiteral("• ")
                     + resourceAudit.messages().join(QStringLiteral("\n• ")));
    }
    addValue(tr("OpenColorIO"),
             state.ocioConfig.isConfigured()
                 ? state.ocioConfig.displayName
                 : tr("Disabled"));
    if (state.ocioConfig.isConfigured()) {
        addValue(tr("OCIO source"), ocioConfigSourceName(state.ocioConfig.source));
        addValue(tr("OCIO version"), state.ocioConfig.version);
        addValue(tr("OCIO fingerprint"),
                 shortenedFingerprint(state.ocioConfig.fingerprint));
        OcioConfigInspection resolvedInspection;
        QString resolveError;
        QString availability;
        if (!resolveOcioConfiguration(state.ocioConfig, &resolvedInspection,
                                      &resolveError)) {
            availability = tr("Unavailable — %1").arg(resolveError);
        } else if (!resolvedInspection.fingerprintMatchesSavedReference) {
            availability = tr("Changed — explicit relink required");
        } else {
            availability = tr("Available and fingerprint-matched");
        }
        addValue(tr("OCIO dependency status"), availability);
        if (state.displayTransform.kind == DisplayTransformKind::OcioView) {
            addValue(tr("OCIO display / view"),
                     tr("%1 / %2").arg(state.displayTransform.ocioDisplay,
                                           state.displayTransform.ocioView));
        }
    }
    layout->addLayout(form);

    auto *note = new QLabel(
        tr("Assign Profile changes the interpretation of the current RGB values without rewriting them. "
           "Convert to Profile rewrites document RGB values and semantic colours to preserve appearance in another working space. "
           "Managed documents apply explicit adjustment-domain contracts. 0.11.0g evaluates presentation and managed adjustment-domain transforms through independently parity-gated WGSL lattices. 0.11.0h adds a separate full-resolution working-to-output export contract with explicit ICC/OCIO conversion, encoded bit depth and optional blue-noise dithering. 0.11.0i–i.3 retain persistence, residency, Smudge and shutdown hardening. 0.12.0a introduces a versioned unified preset envelope with stable identifiers, built-in/user separation, metadata for categories, tags, favourites and recents, atomic storage, import/export support and explicit legacy adjustment/vector migration. 0.12.0b adds one shared searchable management surface for adjustment and vector presets, complete user CRUD, built-in/user/category/favourite/recent filters, metadata editing and preset-file exchange while preserving the compact quick-apply workflows. 0.12.0c adds reusable export profiles with format, bit depth, colour conversion, rendering intent, ICC embedding, dithering, Alpha/matte, quality and validated portable filename templates. 0.12.0d adds a separate multi-output production plan. 0.12.0e captures that plan with an immutable document snapshot in a bounded application queue, adds modeless progress, pause/resume and cancellation controls, and retains atomic per-output failure isolation while documents remain editable. 0.12.0f adds atomic private recovery snapshots, paused startup restoration, explicit collision review, malformed-file quarantine and clean-shutdown preservation without adding queue data to projects or residency snapshots. 0.12.0g hardens the complete preset/export stack with plan-to-resolved-output verification, execution-time Skip decisions, exact progress accounting, completed-worker shutdown classification, bounded iterative layer validation, free-space preflight and explicit no-fallback atomic writes. 0.13.0a adds one non-persisted spatial-filter contract for radius-aware tile halos, edge modes, dirty-region mapping, straight-RGBA Alpha semantics, cancellation, memory bounds and cache identity; the existing Shadows/Highlights CPU kernel now uses it while the established WGSL parity gate remains authoritative. 0.13.0b adds non-destructive Gaussian Blur, Box Blur, Unsharp Mask and High Pass adjustment layers on that shared path, including cumulative tile halos, Alpha-safe hidden RGB, 8/16-bit CPU references, presets and explicit parity-gated GPU fallback. 0.13.0b.2 parallelises the deterministic CPU spatial passes and uses mip-scaled interaction previews before the unchanged level-0 final render. 0.13.0b.3 retains each complete interaction frame until its atomic replacement, eliminating fallback-image flicker during slider drags and release handoff. 0.13.0b.4 keeps Unsharp Mask and High Pass interaction at full-resolution level 0 and adopts the latest completed detail frame directly on release, while Blur retains its responsive mip path. 0.13.0c adds append-only Invert and Photo Filter adjustment layers, advances only adjustment JSON to schema 12, mirrors both in the per-feature WGSL parity gate and retains Vibrance, Threshold and Posterise. 0.13.0d appends Selective Colour with nine colour/tonal families, Relative/Absolute process-colour methods, schema 13, CPU/WGSL and managed-domain parity coverage, expanded advanced-colour presets and Channel Mixer Inspector hardening while retaining project, residency, export queue and recovery envelopes. 0.13.0e appends document-relative Vignette, creative RGB Split and manual radial Chromatic Aberration Correction as IDs 23–25 and schema 14, reusing spatial halos, cancellation, cache and exact CPU fallback while keeping profile-driven lens correction in 0.15.0. 0.13.0f appends Surface Blur, angle-aware Motion Blur and bounded Spin/Zoom Radial Blur as IDs 26–28 and schema 15, adds anisotropic cumulative tile halos, multicore sampling, exact Alpha contracts and cooperative cancellation. 0.13.0g completes the milestone without adding a persisted type: Curves gains on-image sampling and Reset All, Hue/Saturation gains visual/sampleable/resettable targeted ranges, Gradient Map gains duplication/distribution/keyboard editing, and exact large-image histograms use a bounded private worker pool with deterministic reduction and document-safe cancellation. The 0.13.0g.14 fix-up advances adjustment JSON to schema 16 for Vignette Size, migrates older Vignettes to 100%, and adds transient on-canvas geometry controls. 0.13.0g.15a adds schema-8 per-vector-layer Feather state, Inspector editing, grouped Undo and persistence/copy/merge rules. 0.13.0g.15b adds the exact CPU combined-silhouette renderer, fractional and large-radius support, off-canvas coverage, authored-colour propagation and RGBA8/RGBA64 tiled/full reference equality. 0.13.0g.15c adds parity-gated native tiled WGSL coverage convolution, exact fractional kernels, feather-aware tile locality and honest complete CPU fallback. 0.13.0g.15d integrates Feather through rendered canvas-fit bounds, Image Size scaling, exact Expand Stroke semantics, non-lossy editable Merge rules and explicit SVG round-trip compatibility while confirming masks, groups, selections, persistence, residency and flattened exports already consume the shared renderer. 0.13.0g.15e closes the Feather mini-milestone with exact zero-return/bit-depth regressions, tiny and maximum-radius coverage, stroke/winding/cache hardening, conservative GPU preparation memory accounting and private residency-version rejection. Monitor, Display/View and proof transforms never enter exported pixels. Legacy projects and legacy preset files retain their previous interpretation until an explicit user save or update."),
        &dialog);
    note->setWordWrap(true);
    layout->addWidget(note);

    auto *buttons = new QDialogButtonBox(QDialogButtonBox::Close, &dialog);
    connect(buttons, &QDialogButtonBox::rejected, &dialog, &QDialog::reject);
    connect(buttons, &QDialogButtonBox::accepted, &dialog, &QDialog::accept);
    layout->addWidget(buttons);

    layout->activate();
    dialog.setMinimumSize(dialog.minimumSizeHint().expandedTo(QSize(660, 440)));
    dialog.resize(dialog.sizeHint().expandedTo(QSize(760, 520)));

    dialog.exec();
}


std::optional<ColourSpaceDescriptor> MainWindow::chooseDocumentProfile(
    const QString &title,
    const QString &description)
{
    QVector<ColourSpaceDescriptor> profiles;
    const ColourSpaceDescriptor current = document().colourState().workingSpace;
    for (const ColourSpaceDescriptor &candidate : commonWorkingColourSpaces()) {
        if (candidate.stableFingerprint() == current.stableFingerprint()) {
            continue;
        }
        profiles.push_back(candidate);
    }
    const DocumentColourState &colourState = document().colourState();
    if (colourState.ocioConfig.isConfigured()) {
        OcioConfigInspection inspection;
        QString ocioError;
        if (resolveOcioConfiguration(colourState.ocioConfig, &inspection,
                                     &ocioError)
            && inspection.available
            && inspection.fingerprintMatchesSavedReference) {
            for (ColourSpaceDescriptor candidate
                 : ocioWorkingColourSpaces(inspection)) {
                if (candidate.stableFingerprint()
                    == current.stableFingerprint()) {
                    continue;
                }
                profiles.push_back(std::move(candidate));
            }
        }
    }

    QStringList items;
    items.reserve(profiles.size() + 1);
    for (const ColourSpaceDescriptor &profile : profiles) {
        items.push_back(profile.displayName);
    }
    items.push_back(tr("Choose ICC profile from file…"));

    bool accepted = false;
    const QString selected = QInputDialog::getItem(
        this,
        title,
        description,
        items,
        0,
        false,
        &accepted);
    if (!accepted) return std::nullopt;

    const int selectedIndex = items.indexOf(selected);
    if (selectedIndex >= 0 && selectedIndex < profiles.size()) {
        return profiles.at(selectedIndex);
    }

    const QString path = QFileDialog::getOpenFileName(
        this,
        tr("Choose ICC Profile"),
        QString(),
        tr("ICC Profiles (*.icc *.icm);;All Files (*)"));
    if (path.isEmpty()) return std::nullopt;

    ColourSpaceDescriptor descriptor;
    QString error;
    if (!loadExternalIccProfile(path, &descriptor, &error)) {
        QMessageBox::warning(
            this,
            tr("Unsupported ICC Profile"),
            error.isEmpty()
                ? tr("The selected ICC profile could not be loaded.")
                : error);
        return std::nullopt;
    }
    return descriptor;
}

void MainWindow::commitPreparedColourProfileResult(
    const PreparedColourProfileResult &prepared,
    const DocumentState &before,
    const QVector<QUuid> &layerSelection,
    const QString &historyText)
{
    if (!prepared.isValid()) {
        QMessageBox::critical(
            this,
            tr("Colour Profile Change Failed"),
            tr("The prepared colour-profile state is incomplete. The original document is unchanged."));
        return;
    }

    QString commitError;
    if (!document().replaceStructuralState(
            prepared.canvasImage,
            prepared.layers,
            before.selection,
            before.horizontalGuides,
            before.verticalGuides,
            before.resolutionX,
            before.resolutionY,
            prepared.colourState,
            &commitError)) {
        QMessageBox::critical(
            this,
            tr("Colour Profile Change Failed"),
            commitError.isEmpty()
                ? tr("The prepared profile change could not be committed safely. The original document is unchanged.")
                : commitError);
        return;
    }

    session().advanceRenderSerial();
    RenderBackend::instance().resetSessionState(renderSessionContext());
    const DocumentState after = captureDocumentState();
    recordDocumentChange(historyText,
                         before,
                         after,
                         layerSelection,
                         layerSelection);
    refreshLayerTree(document().containsLayer(session().editTargetLayerId())
                         ? session().editTargetLayerId()
                         : document().baseLayerId());
    restoreLayerSelection(layerSelection);
    rebuildInspectorPanel();
    refreshSelectionDisplay();
    updateActionStates();
    updateWindowTitle();
    refreshDisplayColourManagement();
    updateStatusText();
    session().refreshSummary();
    updateDocumentStripEntry(&session());
    schedulePreviewRender();
    scheduleDocumentThumbnail();

    const QString operationName = prepared.operation
            == DocumentProfileOperation::Assign
        ? tr("Assigned") : tr("Converted to");
    statusBar()->showMessage(
        tr("%1 %2. Raster payloads processed: %3; semantic colours converted: %4. One Undo operation.")
            .arg(operationName,
                 prepared.colourState.workingSpace.displayName)
            .arg(prepared.processedRasterImages)
            .arg(prepared.processedSemanticColours),
        6500);
}

void MainWindow::assignDocumentProfile()
{
    if (!document().hasImage() || documentMutationBusy()) return;
    const std::optional<ColourSpaceDescriptor> target = chooseDocumentProfile(
        tr("Assign Profile"),
        tr("Interpret the current document RGB values as (currently %1):")
            .arg(document().colourState().workingSpace.displayName));
    if (!target.has_value()) return;

    if (target->stableFingerprint()
        == document().colourState().workingSpace.stableFingerprint()) {
        statusBar()->showMessage(
            tr("The selected profile is already assigned to this document."),
            3000);
        return;
    }

    const QMessageBox::StandardButton decision = QMessageBox::warning(
        this,
        tr("Assign Profile"),
        tr("Assigning “%1” changes how the existing RGB values are interpreted. "
           "The RGB numbers will not change, so the image may change appearance.\n\n"
           "Use Convert to Profile instead when you want to preserve the current appearance.")
            .arg(target->displayName),
        QMessageBox::Ok | QMessageBox::Cancel,
        QMessageBox::Cancel);
    if (decision != QMessageBox::Ok) return;

    const DocumentState before = captureDocumentState();
    const QVector<QUuid> layerSelection = selectedLayerIds();
    PreparedColourProfileResult prepared;
    QString error;
    if (!prepareAssignedDocumentProfile(document(), *target, &prepared, &error)) {
        QMessageBox::critical(
            this,
            tr("Assign Profile Failed"),
            error.isEmpty()
                ? tr("The selected profile could not be assigned safely.")
                : error);
        return;
    }
    commitPreparedColourProfileResult(
        prepared,
        before,
        layerSelection,
        tr("Assign Profile — %1").arg(target->displayName));
}

void MainWindow::convertDocumentProfile()
{
    if (!document().hasImage() || documentMutationBusy()) return;
    const ColourSpaceDescriptor source = document().colourState().workingSpace;
    if (source.isUntagged()
        || (source.kind != ColourSpaceKind::Ocio
            && !source.toQColorSpace().isValid())) {
        QMessageBox::information(
            this,
            tr("Assign a Source Profile First"),
            tr("This document is untagged. Assign the profile that describes its current RGB values before converting it to another profile."));
        return;
    }

    const std::optional<ColourSpaceDescriptor> target = chooseDocumentProfile(
        tr("Convert to Profile"),
        tr("Convert from %1 into this working profile:")
            .arg(source.displayName));
    if (!target.has_value()) return;
    if (target->stableFingerprint() == source.stableFingerprint()) {
        statusBar()->showMessage(
            tr("The document is already in the selected working profile."),
            3000);
        return;
    }

    const QMessageBox::StandardButton decision = QMessageBox::question(
        this,
        tr("Convert to Profile"),
        tr("Convert the document from “%1” to “%2”?\n\n"
           "Raster pixels, vector fills and strokes, text colours, and Gradient Map stops will be converted to preserve appearance. "
           "Alpha, masks and selections will not be changed. The operation is transactional and can be undone once.")
            .arg(source.displayName, target->displayName),
        QMessageBox::Yes | QMessageBox::Cancel,
        QMessageBox::Cancel);
    if (decision != QMessageBox::Yes) return;

    const DocumentState before = captureDocumentState();
    const QVector<QUuid> layerSelection = selectedLayerIds();
    const QUuid sessionId = session().id();
    const quint64 renderSerial = session().renderSerial();
    const PhotoDocument documentSnapshot = document();

    m_colourProfileCancelToken = std::make_shared<std::atomic_bool>(false);
    const std::shared_ptr<std::atomic_bool> cancelToken =
        m_colourProfileCancelToken;
    m_colourProfileOperationInProgress = true;
    updateActionStates();

    auto *progress = new QProgressDialog(
        tr("Converting raster pixels and document colours from %1 to %2…")
            .arg(source.displayName, target->displayName),
        tr("Cancel"),
        0,
        0,
        this);
    progress->setWindowTitle(tr("Convert to Profile"));
    progress->setWindowModality(Qt::WindowModal);
    progress->setMinimumDuration(0);
    connect(progress, &QProgressDialog::canceled, this,
            [progress, cancelToken] {
                cancelToken->store(true, std::memory_order_release);
                progress->setLabelText(
                    QObject::tr("Cancelling profile conversion…"));
                progress->setCancelButton(nullptr);
            });
    progress->show();

    auto *watcher = new QFutureWatcher<PreparedColourProfileResult>(this);
    connect(watcher, &QFutureWatcher<PreparedColourProfileResult>::finished,
            this,
            [this, watcher, progress, sessionId, renderSerial, before,
             layerSelection, cancelToken, target] {
                const PreparedColourProfileResult prepared = watcher->result();
                const bool userCancelled = cancelToken->load(
                    std::memory_order_acquire);
                const QString workerError = prepared.error;
                watcher->deleteLater();
                {
                    const QSignalBlocker blocker(progress);
                    progress->close();
                }
                progress->deleteLater();
                m_colourProfileCancelToken.reset();
                m_colourProfileOperationInProgress = false;
                updateActionStates();

                if (prepared.cancelled || userCancelled) {
                    statusBar()->showMessage(
                        tr("Profile conversion cancelled; the document was not changed."),
                        4000);
                    return;
                }
                if (!workerError.isEmpty() || !prepared.isValid()) {
                    QMessageBox::critical(
                        this,
                        tr("Convert to Profile Failed"),
                        workerError.isEmpty()
                            ? tr("The profile conversion could not be prepared safely. The original document is unchanged.")
                            : workerError);
                    return;
                }

                DocumentSession *targetSession = sessionById(sessionId);
                if (!targetSession || targetSession != m_activeSession
                    || targetSession->renderSerial() != renderSerial
                    || document().sourceImage().cacheKey()
                        != before.canvasImage.cacheKey()
                    || !layerTreesEqual(document().layers(), before.layers)
                    || document().colourStateRevision()
                        != before.colourState.revision
                    || !document().colourState().semanticallyEquals(
                        before.colourState)) {
                    statusBar()->showMessage(
                        tr("Profile conversion result discarded because the document changed."),
                        4500);
                    return;
                }

                commitPreparedColourProfileResult(
                    prepared,
                    before,
                    layerSelection,
                    tr("Convert to Profile — %1").arg(target->displayName));
            });

    watcher->setFuture(QtConcurrent::run(
        [documentSnapshot, selectedTarget = *target, cancelToken] {
            PreparedColourProfileResult prepared;
            QString error;
            if (!prepareConvertedDocumentProfile(
                    documentSnapshot,
                    selectedTarget,
                    &prepared,
                    cancelToken.get(),
                    &error)) {
                prepared.cancelled = cancelToken->load(
                    std::memory_order_acquire);
                prepared.error = error;
            }
            return prepared;
        }));
}

bool MainWindow::resolveImportedImageColour(QImage *image,
                                            ImageColourImportInfo *colourInfo,
                                            const QString &sourceLabel)
{
    if (!image || image->isNull() || !colourInfo
        || !colourInfo->requiresUntaggedPolicy()) {
        return image && !image->isNull();
    }

    UntaggedImagePolicy policy = storedUntaggedImagePolicy();
    if (policy == UntaggedImagePolicy::Ask) {
        QMessageBox box(this);
        box.setIcon(colourInfo->sourceStatus == InputProfileStatus::InvalidOrUnsupported
                        ? QMessageBox::Warning : QMessageBox::Question);
        box.setWindowTitle(colourInfo->sourceStatus == InputProfileStatus::InvalidOrUnsupported
                               ? tr("Unusable Embedded Colour Profile")
                               : tr("Untagged Image"));
        box.setText(colourInfo->sourceStatus == InputProfileStatus::InvalidOrUnsupported
                        ? tr("%1 declares an embedded colour profile, but it could not be used.")
                              .arg(sourceLabel)
                        : tr("%1 does not contain an embedded colour profile.")
                              .arg(sourceLabel));
        box.setInformativeText(
            tr("Choose how the existing RGB values should be interpreted. Opening or creating a document will not rewrite them; "
               "Paste into a differently tagged document may convert them into that document's current space."));
        auto *assumeButton = box.addButton(tr("Assume sRGB"),
                                           QMessageBox::AcceptRole);
        auto *leaveButton = box.addButton(tr("Leave Untagged"),
                                          QMessageBox::ActionRole);
        box.addButton(QMessageBox::Cancel);
        auto *remember = new QCheckBox(tr("Use this choice for future untagged images"),
                                       &box);
        box.setCheckBox(remember);
        box.setDefaultButton(qobject_cast<QPushButton *>(assumeButton));
        box.exec();
        if (box.clickedButton() == assumeButton) {
            policy = UntaggedImagePolicy::AssumeSRgb;
        } else if (box.clickedButton() == leaveButton) {
            policy = UntaggedImagePolicy::LeaveUntagged;
        } else {
            return false;
        }
        if (remember->isChecked()) storeUntaggedImagePolicy(policy);
    }

    applyUntaggedImagePolicy(image, colourInfo, policy);
    return true;
}

bool MainWindow::resolveClipboardColourPolicy(ClipboardPayload *payload,
                                              ImageColourImportInfo *colourInfo,
                                              const QString &sourceLabel)
{
    if (!payload || !payload->isValid() || !colourInfo) return false;
    *colourInfo = inspectClipboardColourProfile(
        payload->image, payload->sourceKind != ClipboardSourceKind::ExternalImage);
    return resolveImportedImageColour(&payload->image, colourInfo, sourceLabel);
}

void MainWindow::showImageProfileWarnings(const QString &sourceLabel,
                                          const QStringList &warnings)
{
    if (warnings.isEmpty()
        || !QSettings().value(QString::fromLatin1(ShowImportWarningsSettingsKey),
                              true).toBool()) {
        return;
    }
    QStringList displayed = warnings;
    displayed.removeDuplicates();
    constexpr int MaximumDisplayedWarnings = 8;
    if (displayed.size() > MaximumDisplayedWarnings) {
        const int hidden = displayed.size() - MaximumDisplayedWarnings;
        displayed = displayed.mid(0, MaximumDisplayedWarnings);
        displayed.push_back(tr("…and %1 more warning(s)").arg(hidden));
    }
    QMessageBox::warning(
        this,
        tr("Colour-Profile Warning"),
        tr("%1 was processed successfully and its pixel values were preserved:\n\n• %2")
            .arg(sourceLabel, displayed.join(QStringLiteral("\n• "))));
}

void MainWindow::newDocumentFromClipboard()
{
    if (documentMutationBusy()) {
        statusBar()->showMessage(
            tr("Finish the current edit or export before creating another document."),
            3000);
        return;
    }

    QString error;
    const std::optional<ClipboardPayload> sourcePayload = systemClipboardPayload(&error);
    if (!sourcePayload) {
        QMessageBox::information(
            this,
            tr("No Clipboard Image"),
            error.isEmpty() ? tr("The clipboard does not contain an image.") : error);
        return;
    }

    ClipboardPayload payload = *sourcePayload;
    ImageColourImportInfo colourInfo;
    if (!resolveClipboardColourPolicy(&payload,
                                      &colourInfo,
                                      tr("the clipboard image"))) {
        return;
    }
    QImage image = clipboardPayloadAsNewDocumentRaster(
        payload, payload.image.colorSpace(), &error);
    if (image.isNull()) {
        QMessageBox::critical(
            this,
            tr("Could Not Create Clipboard Document"),
            error.isEmpty()
                ? tr("The clipboard image could not be prepared as a document.")
                : error);
        return;
    }

    PhotoDocument candidate;
    candidate.setSourceImage(image, QString(), colourInfo);

    DocumentSession *target = createDocumentSession();
    if (target != m_activeSession) {
        captureActiveSessionUiState();
        resetPreviewControllerForSessionSwitch();
        if (!setActiveSession(target)) {
            return;
        }
    }
    initialiseActiveDocument(std::move(candidate), true);
    const QString profileNote = colourInfo.policyWasApplied
        ? (colourInfo.appliedPolicy == UntaggedImagePolicy::AssumeSRgb
               ? tr("; untagged pixels were interpreted as sRGB")
               : tr("; pixels remain untagged"))
        : tr("; %1 retained").arg(document().colourProfileName());
    statusBar()->showMessage(
        tr("Created a %1 × %2 document from the clipboard%3%4.")
            .arg(image.width())
            .arg(image.height())
            .arg(image.depth() > 32 ? tr(" at 16-bit precision") : QString())
            .arg(profileNote),
        4500);
    showImageProfileWarnings(tr("Clipboard image"), colourInfo.warnings);
}

