void MainWindow::moveLayerEffectInLayer(const QUuid &layerId,
                                         const QUuid &effectId,
                                         const int delta)
{
    if (documentMutationBusy() || layerId.isNull() || effectId.isNull()
        || delta == 0 || !document().containsLayer(layerId)) return;
    const LayerNode owner = document().layerById(layerId);
    int sourceIndex = -1;
    for (int index = 0; index < owner.layerEffects.size(); ++index) {
        if (owner.layerEffects.at(index).id == effectId) { sourceIndex = index; break; }
    }
    if (sourceIndex < 0) return;
    const int destination = std::clamp(sourceIndex + delta, 0,
                                       static_cast<int>(owner.layerEffects.size()) - 1);
    if (destination == sourceIndex) return;
    const DocumentState before = captureDocumentState();
    const QVector<QUuid> selection = selectedLayerIds();
    if (!document().moveLayerEffect(layerId, effectId, destination)) return;
    recordDocumentChange(delta < 0 ? tr("Move Layer Effect Up")
                                   : tr("Move Layer Effect Down"),
                         before, captureDocumentState(), selection, {layerId});
    refreshLayerTree(layerId);
    selectLayerEffectTreeItem(layerId, effectId);
    rebuildInspectorPanel();
    updateWindowTitle();
    updateActionStates();
    updateStatusText();
    schedulePreviewRender();
    scheduleDocumentThumbnail();
}

