        addIntegerOption(tr("Hardness"), 0, 100, m_healHardness, tr("%"));
        auto *hint = new QLabel(
            tr("Alt-click inside the image to sample detail, then paint. Destination Alpha is preserved."),
            m_toolOptionsBar);
        hint->setObjectName(QStringLiteral("MutedLabel"));
        m_toolOptionsBar->addWidget(hint);
        break;
