        addIntegerOption(tr("Size"), 1, 2000, m_spotHealSize, tr(" px"));
        addIntegerOption(tr("Opacity"), 1, 100, m_spotHealOpacity, tr("%"));
        addIntegerOption(tr("Hardness"), 0, 100, m_spotHealHardness, tr("%"));
        auto *hint = new QLabel(
            tr("Paint over a blemish. A nearby non-overlapping source is selected automatically when the stroke finishes."),
            m_toolOptionsBar);
        hint->setObjectName(QStringLiteral("MutedLabel"));
