void MainWindow::addDoubleControl(const QString &label,
                                  const double minimum,
                                  const double maximum,
                                  const double step,
                                  const double value,
                                  const int decimals,
                                  const std::function<void(double)> &setter)
{
    auto *labelWidget = new QLabel(label, m_inspectorContainer);
    m_inspectorLayout->addWidget(labelWidget);

    auto *control = new SliderSpinBox(m_inspectorContainer);
    control->configure(minimum, maximum, step, decimals);
    control->setValue(value);
    m_inspectorLayout->addWidget(control);

    connect(control, &SliderSpinBox::interactionStarted, this, [this, label] {
        beginPropertyUndo(tr("Edit %1").arg(label));
    });
    connect(control, &SliderSpinBox::interactionFinished,
            this, &MainWindow::finishPropertyUndo);
    connect(control, &SliderSpinBox::valueChanged,
            this, [setter](const double actual) { setter(actual); });
    connect(control, &QObject::destroyed, this, [this] {
        // An Inspector rebuild must not strand an unfinished numeric edit.
        finishPropertyUndo();
    });
}

void MainWindow::clearInspectorLayout()
{
    m_levelsHistogramRefreshTimer.stop();
    m_levelsEditor = nullptr;
    m_curvesEditor = nullptr;
    m_levelsEditorLayerId = {};
    m_curvesEditorLayerId = {};
    clearOneShotAdjustmentEyedroppers();
    if (m_histogramService) {
        m_histogramService->cancel();
    }
    if (!m_inspectorLayout) {
        return;
    }

    const auto clearLayout = [](QLayout *layout, const auto &self) -> void {
        while (QLayoutItem *item = layout->takeAt(0)) {
            if (QWidget *widget = item->widget()) {
                // Remove and hide the old page synchronously so it cannot remain
                // visible behind the replacement. Destruction stays deferred:
                // an Inspector rebuild can be triggered from one of these
                // controls' own signals, where deleting the sender immediately
                // would be unsafe.
                widget->hide();
                widget->setParent(nullptr);
                widget->deleteLater();
            } else if (QLayout *childLayout = item->layout()) {
                // Older pages placed spin boxes directly in nested layouts, so
                // walk every level rather than clearing only top-level widgets.
                self(childLayout, self);
            }
            delete item;
        }
    };
    clearLayout(m_inspectorLayout, clearLayout);
}

bool MainWindow::maybeSaveChanges()
{
    return maybeSaveChanges(m_activeSession);
}

bool MainWindow::maybeSaveChanges(DocumentSession *targetSession)
{
    if (!targetSession) {
        return true;
    }
    if (targetSession->document().hasImage()) {
        targetSession->refreshSummary();
    }
    const DocumentSession::Summary &summary = targetSession->summary();
    const bool hasDocument = targetSession->document().hasImage()
        || !summary.pixelSize.isEmpty();
    const bool modified = targetSession->document().hasImage()
        ? targetSession->document().isModified()
        : summary.modified;
    if (!hasDocument || !modified) {
        return true;
    }

    const QString displayName = summary.displayName.isEmpty()
        ? tr("Untitled")
        : summary.displayName;
    const QMessageBox::StandardButton choice = QMessageBox::warning(
        this,
        tr("Unsaved Changes"),
        tr("Save changes to %1?").arg(displayName),
        QMessageBox::Save | QMessageBox::Discard | QMessageBox::Cancel,
        QMessageBox::Save);

    if (choice == QMessageBox::Cancel) {
        return false;
    }
    if (choice == QMessageBox::Discard) {
        return true;
    }

    if (targetSession != m_activeSession && !activateDocumentSession(targetSession)) {
        QMessageBox::critical(this,
                              tr("Could Not Restore Document"),
                              tr("The document could not be restored from its private session cache, so it was not closed."));
        return false;
    }
    if (!document().hasImage()) {
        return false;
    }
    if (document().projectPath().isEmpty()) {
        return saveProjectAs();
    }
    return writeProjectTo(document().projectPath());
}

bool MainWindow::writeProjectTo(const QString &filePath)
{
    if (session().isSmartSourceEditor()) {
        return saveSmartSourceEditor(&session());
    }
    if (!m_canvasTextEditLayerId.isNull()) {
        commitCanvasTextEditing();
    }
    QString error;
    if (!document().saveProject(filePath, &error)) {
        QMessageBox::critical(this,
                              tr("Could Not Save Project"),
                              tr("%1\n\n%2").arg(filePath, error));
        return false;
    }

    const QUuid savedDocumentId = document().documentIdentity();
    refreshOpenLinkedDependents(savedDocumentId, filePath);

    session().baselineRequiresSave() = false;
    undoStack()->setClean();
    document().setModified(false);
    session().refreshSummary();
    updateWindowTitle();
    updateDocumentStripEntry(&session());
    const CropSessionState &crop = session().cropState();
    const QRectF fullCanvas(QPointF(), QSizeF(document().sourceImage().size()));
    const bool pendingCrop = crop.initialised
        && (crop.frame.normalized() != fullCanvas
            || std::abs(crop.straightenAngle) > 1.0e-6);
    statusBar()->showMessage(
        pendingCrop
            ? tr("Saved %1. The pending Crop frame was not applied or saved.")
                  .arg(QFileInfo(filePath).fileName())
            : tr("Saved %1").arg(QFileInfo(filePath).fileName()),
        pendingCrop ? 6000 : 4000);
    return true;
}

